css:
.bkn-iris {
  --bkn-iris-night: oklch(0.205 0.012 65);
  --bkn-iris-bone: oklch(0.935 0.018 85);
  --bkn-iris-brass: oklch(0.77 0.085 80);
  --bkn-iris-muted: color-mix(in oklch, var(--bkn-iris-bone) 56%, var(--bkn-iris-night));
  --bkn-iris-line: color-mix(in oklch, var(--bkn-iris-bone) 14%, transparent);
  --bkn-iris-deep: color-mix(in oklch, var(--bkn-iris-brass) 62%, var(--bkn-iris-night));
  --bkn-iris-veil-muted: color-mix(in oklch, var(--bkn-iris-night) 52%, var(--bkn-iris-bone));
  --bkn-iris-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --bkn-iris-mono: ui-monospace, Menlo, Consolas, monospace;
  --bkn-iris-out: cubic-bezier(.16, 1, .3, 1);
  --bkn-iris-iris: cubic-bezier(.77, 0, .18, 1);
  --bkn-iris-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  --bkn-iris-gut: clamp(16px, 4.6cqi, 56px);
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  width: 100%;
  min-height: 580px;
  display: grid;
  grid-template-rows: auto 1fr;
  background: var(--bkn-iris-night);
  color: var(--bkn-iris-bone);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, p, ol, li, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(a, button):focus-visible { outline: 1.5px solid var(--bkn-iris-brass); outline-offset: 4px; border-radius: 2px; }
}

.bkn-iris-bar {
  position: relative;
  z-index: 4;
  display: grid;
  grid-template-columns: auto 1fr auto;
  grid-template-areas: "logo . btn";
  align-items: center;
  gap: 24px;
  padding: 20px var(--bkn-iris-gut);
  border-bottom: 1px solid var(--bkn-iris-line);
  transition: color .45s var(--bkn-iris-out) .1s, border-color .45s var(--bkn-iris-out) .1s;
}
.bkn-iris-logo {
  grid-area: logo;
  display: flex;
  align-items: center;
  gap: 12px;
  & svg { width: 34px; height: 34px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
}
.bkn-iris-wm {
  display: grid;
  line-height: 1.05;
  & b { font: 400 20px/1.05 var(--bkn-iris-serif); letter-spacing: -.01em; }
  & small { font-size: 9.5px; letter-spacing: .22em; text-transform: uppercase; color: var(--bkn-iris-muted); margin-top: 3px; transition: color .45s var(--bkn-iris-out) .1s; }
}
.bkn-iris-tag, .bkn-iris-enq { display: none; }
.bkn-iris-tag {
  grid-area: tag;
  justify-self: center;
  font-size: 12px;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--bkn-iris-muted);
  & span { color: var(--bkn-iris-brass); margin-inline: .5em; }
}
.bkn-iris-enq {
  grid-area: enq;
  font-size: 14px;
  padding-block: 4px;
  background: linear-gradient(var(--bkn-iris-brass), var(--bkn-iris-brass)) 0 100% / 100% 1px no-repeat;
  transition: background-size .5s var(--bkn-iris-out), opacity .3s;
  &:hover { background-size: 0 1px; background-position: 100% 100%; }
}

.bkn-iris-btn {
  grid-area: btn;
  display: inline-flex;
  align-items: center;
  gap: 14px;
  height: 44px;
  padding: 0 16px 0 20px;
  border: 1px solid color-mix(in oklch, currentColor 30%, transparent);
  border-radius: 999px;
  font-size: 13px;
  letter-spacing: .12em;
  text-transform: uppercase;
  transition: border-color .3s, background-color .3s;
  &:hover { background: color-mix(in oklch, currentColor 8%, transparent); border-color: color-mix(in oklch, currentColor 55%, transparent); }
  &:focus-visible { outline-offset: 3px; border-radius: 999px; }
}
.bkn-iris-roll {
  display: grid;
  height: 1.5em;
  overflow: clip;
  line-height: 1.5;
  & span { transition: translate .55s var(--bkn-iris-out); }
}
.bkn-iris-burger {
  position: relative;
  width: 22px;
  height: 10px;
  & i {
    position: absolute;
    left: 0;
    width: 100%;
    height: 1.5px;
    border-radius: 2px;
    background: currentColor;
    transform-origin: 50% 50%;
    /* closing: un-cross first, then spread */
    transition: rotate .3s cubic-bezier(.5, 0, .5, 1), translate .35s var(--bkn-iris-spring) .22s, scale .3s var(--bkn-iris-out);
  }
  & i:first-child { top: 0; }
  & i:last-child { bottom: 0; scale: .64 1; transform-origin: 100% 50%; }
}
.bkn-iris-btn:hover .bkn-iris-burger i:last-child { scale: 1 1; }

.bkn-iris.is-open {
  & .bkn-iris-bar { color: var(--bkn-iris-night); border-color: color-mix(in oklch, var(--bkn-iris-night) 12%, transparent); }
  & .bkn-iris-wm small { color: var(--bkn-iris-veil-muted); }
  & .bkn-iris-tag, & .bkn-iris-enq { opacity: 0; transition: opacity .2s; }
  & .bkn-iris-roll span { translate: 0 -100%; }
  & .bkn-iris-burger i {
    /* opening: converge first, then cross */
    transition: translate .28s cubic-bezier(.5, 0, .5, 1), rotate .5s var(--bkn-iris-spring) .2s, scale .25s var(--bkn-iris-out);
  }
  & .bkn-iris-burger i:first-child { translate: 0 4.25px; rotate: 45deg; }
  & .bkn-iris-burger i:last-child { translate: 0 -4.25px; rotate: -45deg; scale: 1 1; transform-origin: 50% 50%; }
}

/* ---------- hero at rest ---------- */
.bkn-iris-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "art" "kick" "h" "lede" "facts";
  align-content: end;
  gap: 18px;
  padding: clamp(36px, 6cqi, 72px) var(--bkn-iris-gut) clamp(28px, 4.6cqi, 56px);
}
.bkn-iris-kick {
  grid-area: kick;
  display: flex;
  gap: 14px;
  align-items: center;
  font-size: 11.5px;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: var(--bkn-iris-muted);
  &::before { content: ""; width: 28px; height: 1px; background: var(--bkn-iris-brass); }
}
.bkn-iris-mono { font-family: var(--bkn-iris-mono); letter-spacing: .06em; font-variant-numeric: tabular-nums; }
.bkn-iris-h {
  grid-area: h;
  font: 400 clamp(42px, 6.6cqi + 12px, 92px)/.98 var(--bkn-iris-serif);
  letter-spacing: -.025em;
  text-wrap: balance;
  max-width: 12ch;
  & em { font-style: italic; color: var(--bkn-iris-brass); }
}
.bkn-iris-lede {
  grid-area: lede;
  max-width: 46ch;
  color: var(--bkn-iris-muted);
  font-size: clamp(15px, .5cqi + 12.5px, 17px);
  text-wrap: pretty;
}
.bkn-iris-facts {
  grid-area: facts;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-top: 10px;
  border-top: 1px solid var(--bkn-iris-line);
  max-width: 520px;
  & div { display: flex; flex-direction: column-reverse; justify-content: flex-end; padding: 14px 12px 0 0; }
  & div + div { padding-left: 16px; border-left: 1px solid var(--bkn-iris-line); }
  & dt { font-size: 11px; letter-spacing: .14em; text-transform: uppercase; color: var(--bkn-iris-muted); }
  & dd { font: 400 clamp(28px, 2cqi + 18px, 40px)/1.1 var(--bkn-iris-serif); font-variant-numeric: tabular-nums lining-nums; }
}
.bkn-iris-art { grid-area: art; width: min(64%, 300px); height: auto; margin-bottom: 6px; overflow: visible; }
.bkn-iris-draw path {
  fill: none;
  stroke: var(--bkn-iris-brass);
  stroke-width: 1.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: bkn-iris-draw 1.8s cubic-bezier(.65, 0, .25, 1) calc(var(--i) * 160ms + 250ms) forwards;
}
.bkn-iris-dim {
  & path { fill: none; stroke: var(--bkn-iris-muted); stroke-width: .8; }
  & text { font: 9.5px var(--bkn-iris-mono); letter-spacing: .12em; fill: var(--bkn-iris-muted); }
  opacity: 0;
  animation: bkn-iris-fade .9s var(--bkn-iris-out) 1.4s forwards;
}
@keyframes bkn-iris-draw { to { stroke-dashoffset: 0; } }
@keyframes bkn-iris-fade { to { opacity: 1; } }

/* ---------- the veil ---------- */
.bkn-iris-veil {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: 1fr auto;
  grid-template-areas: "list" "meta";
  gap: 24px;
  padding: 108px var(--bkn-iris-gut) 24px;
  background: var(--bkn-iris-bone);
  color: var(--bkn-iris-night);
  visibility: hidden;
  clip-path: circle(0px at var(--bkn-iris-x, calc(100% - 60px)) var(--bkn-iris-y, 42px));
  transition: clip-path .7s var(--bkn-iris-iris) .12s, visibility 0s linear .82s;
}
.bkn-iris.is-open .bkn-iris-veil {
  visibility: visible;
  clip-path: circle(var(--bkn-iris-r, 150%) at var(--bkn-iris-x, calc(100% - 60px)) var(--bkn-iris-y, 42px));
  transition: clip-path .95s var(--bkn-iris-iris), visibility 0s;
}
.bkn-iris-nav { grid-area: list; align-self: center; }
.bkn-iris-list {
  display: grid;
  & li { border-bottom: 1px solid color-mix(in oklch, var(--bkn-iris-night) 10%, transparent); }
  & li:first-child { border-top: 1px solid color-mix(in oklch, var(--bkn-iris-night) 10%, transparent); }
  & a {
    display: grid;
    grid-template-columns: clamp(30px, 5cqi, 64px) auto auto 1fr;
    align-items: center;
    column-gap: clamp(8px, 1.4cqi, 18px);
    padding-block: clamp(2px, .5cqi, 6px);
    font: 400 clamp(34px, 4.6cqi + 14px, 70px)/1.08 var(--bkn-iris-serif);
    letter-spacing: -.022em;
    transition: opacity .4s var(--bkn-iris-out), color .4s;
  }
  & a:focus-visible { outline-offset: -2px; }
  & sup {
    align-self: start;
    margin-top: .5em;
    font: 500 11px/1 var(--bkn-iris-mono);
    letter-spacing: .06em;
    color: var(--bkn-iris-deep);
    font-variant-numeric: tabular-nums;
    opacity: 0;
    transition: opacity .2s;
  }
}
.bkn-iris-n {
  font: 500 11px/1 var(--bkn-iris-mono);
  letter-spacing: .14em;
  color: var(--bkn-iris-veil-muted);
  font-variant-numeric: tabular-nums;
  transition: color .3s;
}
.bkn-iris-w {
  display: block;
  overflow: clip;
  padding-block: .04em .1em;
  transition: translate .6s var(--bkn-iris-out);
  & > span {
    display: block;
    translate: 0 110%;
    transition: translate .45s cubic-bezier(.6, 0, .9, .4) calc((4 - var(--i)) * 28ms);
  }
}
.bkn-iris-arr {
  justify-self: end;
  width: clamp(28px, 3.4cqi, 48px);
  height: auto;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.3;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0;
  translate: -14px 0;
  transition: opacity .35s, translate .5s var(--bkn-iris-out);
}
.bkn-iris-list li { --bkn-iris-d: calc(var(--i) * 70ms + 300ms); }
.bkn-iris.is-open .bkn-iris-list {
  & .bkn-iris-w > span { translate: 0 0; transition: translate 1s var(--bkn-iris-out) var(--bkn-iris-d); }
  & sup { opacity: 1; transition: opacity .6s var(--bkn-iris-out) calc(var(--bkn-iris-d) + 350ms); }
}
.bkn-iris-list:has(a:is(:hover, :focus-visible)) a:not(:is(:hover, :focus-visible)) { opacity: .34; }
.bkn-iris-list a:is(:hover, :focus-visible) {
  & .bkn-iris-w { translate: .22em 0; }
  & .bkn-iris-n { color: var(--bkn-iris-deep); }
  & .bkn-iris-arr { opacity: 1; translate: 0 0; }
}
.bkn-iris-list a[aria-current="page"] .bkn-iris-n::after { content: " ·"; color: var(--bkn-iris-deep); }

.bkn-iris-pv { display: none; }
.bkn-iris-frame {
  position: relative;
  overflow: clip;
  aspect-ratio: 4 / 5;
  max-height: 100%;
  background: color-mix(in oklch, var(--bkn-iris-night) 10%, var(--bkn-iris-bone));
}
.bkn-iris-shot {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  clip-path: inset(100% 0 0 0);
  scale: 1.08;
  transition: clip-path .75s var(--bkn-iris-iris), scale 1.2s var(--bkn-iris-out);
  &.is-prev { clip-path: inset(0 0 0 0); scale: 1; z-index: 1; transition: none; }
  &.is-on { clip-path: inset(0 0 0 0); scale: 1; z-index: 2; }
}
.bkn-iris-cap {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 12px;
  font-size: 12.5px;
  & b { font: 400 16px/1.3 var(--bkn-iris-serif); }
  & span { color: var(--bkn-iris-veil-muted); font-family: var(--bkn-iris-mono); font-size: 11px; letter-spacing: .04em; align-self: end; text-align: right; }
}
.bkn-iris-meta {
  grid-area: meta;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 24px;
  padding-top: 18px;
  font-size: 13px;
  line-height: 1.55;
  color: color-mix(in oklch, var(--bkn-iris-night) 80%, var(--bkn-iris-bone));
  & p { opacity: 0; translate: 0 8px; transition: opacity .2s, translate .2s; }
  & p:last-child { grid-column: 1 / -1; }
  & small { display: block; font-size: 10.5px; letter-spacing: .2em; text-transform: uppercase; color: var(--bkn-iris-deep); margin-bottom: 4px; }
  & a { background: linear-gradient(currentColor, currentColor) 0 100% / 0 1px no-repeat; transition: background-size .4s var(--bkn-iris-out); }
  & a:hover { background-size: 100% 1px; }
}
.bkn-iris.is-open .bkn-iris-meta p { opacity: 1; translate: 0 0; transition: opacity .8s var(--bkn-iris-out) calc(var(--i) * 80ms + 650ms), translate .8s var(--bkn-iris-out) calc(var(--i) * 80ms + 650ms); }

@container (min-width: 560px) {
  .bkn-iris-enq { display: inline-block; }
  .bkn-iris-bar { grid-template-columns: auto 1fr auto auto; grid-template-areas: "logo . enq btn"; }
  .bkn-iris-meta { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bkn-iris-meta p:last-child { grid-column: auto; }
}
@container (min-width: 780px) {
  .bkn-iris-hero {
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
    grid-template-areas: "kick art" "h art" "lede art" "facts art";
    column-gap: 6cqi;
  }
  .bkn-iris-art { width: 100%; margin: 0; align-self: center; }
  .bkn-iris-veil {
    grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
    grid-template-areas: "list pv" "meta meta";
    column-gap: 6cqi;
  }
  .bkn-iris-pv {
    grid-area: pv;
    display: grid;
    align-content: center;
    justify-self: end;
    width: min(100%, 340px);
    opacity: 0;
    translate: 0 16px;
    transition: opacity .25s, translate .25s;
  }
  .bkn-iris.is-open .bkn-iris-pv { opacity: 1; translate: 0 0; transition: opacity .9s var(--bkn-iris-out) .5s, translate 1s var(--bkn-iris-out) .5s; }
}
@container (min-width: 980px) {
  .bkn-iris-tag { display: block; }
  .bkn-iris-bar { grid-template-columns: auto 1fr auto auto; grid-template-areas: "logo tag enq btn"; }
}

@media (prefers-reduced-motion: reduce) {
  .bkn-iris .bkn-iris-veil { clip-path: none; opacity: 0; transition: opacity .2s linear, visibility 0s linear .2s; }
  .bkn-iris.is-open .bkn-iris-veil { clip-path: none; opacity: 1; transition: opacity .2s linear, visibility 0s; }
  .bkn-iris .bkn-iris-w > span, .bkn-iris.is-open .bkn-iris-w > span { translate: none; transition: none; }
  .bkn-iris .bkn-iris-list sup, .bkn-iris .bkn-iris-meta p, .bkn-iris .bkn-iris-pv { translate: none; transition: opacity .2s linear; }
  .bkn-iris .bkn-iris-burger i, .bkn-iris .bkn-iris-roll span, .bkn-iris.is-open .bkn-iris-burger i { transition-duration: .01s; transition-delay: 0s; }
  .bkn-iris .bkn-iris-shot { scale: 1; transition: opacity .25s linear; clip-path: none; opacity: 0; }
  .bkn-iris .bkn-iris-shot.is-on, .bkn-iris .bkn-iris-shot.is-prev { opacity: 1; }
  .bkn-iris .bkn-iris-draw path { animation: none; stroke-dashoffset: 0; }
  .bkn-iris .bkn-iris-dim { animation: none; opacity: 1; }
  .bkn-iris .bkn-iris-w, .bkn-iris .bkn-iris-arr { transition: opacity .2s linear; translate: none; }
}

