const btn = root.querySelector(".bkn-iris-btn");
const veil = root.querySelector(".bkn-iris-veil");
const links = [...root.querySelectorAll(".bkn-iris-list a")];
const shots = [...root.querySelectorAll(".bkn-iris-shot")];
const capB = root.querySelector(".bkn-iris-cap b");
const capS = root.querySelector(".bkn-iris-cap span");
const behind = [...root.querySelectorAll(".bkn-iris-hero, .bkn-iris-logo, .bkn-iris-enq")];
const CAPS = [
  ["Kalkværket Housing", "Aarhus · 112 homes · 2025"],
  ["The long table", "Islands Brygge · 38 people, one room"],
  ["On thick walls", "Essay 28 · 14 min read"],
  ["The sample library", "112 materials · lime, oak, zinc, cork"],
  ["Two studios", "Copenhagen ↔ Lisbon · 2,480 km"]
];
let open = false;
let cur = 0;

// The iris is centred on the burger and sized to the farthest corner of the
// component, so it always just covers it — at 380px and at 1440px alike.
function origin() {
  const r = root.getBoundingClientRect();
  const b = btn.getBoundingClientRect();
  const x = b.left + b.width / 2 - r.left;
  const y = b.top + b.height / 2 - r.top;
  const R = Math.hypot(Math.max(x, r.width - x), Math.max(y, r.height - y)) + 4;
  root.style.setProperty("--bkn-iris-x", x.toFixed(1) + "px");
  root.style.setProperty("--bkn-iris-y", y.toFixed(1) + "px");
  root.style.setProperty("--bkn-iris-r", R.toFixed(1) + "px");
}

function show(i) {
  if (i === cur) return;
  shots.forEach((s, k) => {
    s.classList.toggle("is-prev", k === cur);
    s.classList.toggle("is-on", k === i);
  });
  cur = i;
  capB.textContent = CAPS[i][0];
  capS.textContent = CAPS[i][1];
}

function setOpen(v, returnFocus) {
  if (v === open) return;
  open = v;
  origin();
  root.classList.toggle("is-open", v);
  btn.setAttribute("aria-expanded", String(v));
  btn.setAttribute("aria-label", v ? "Close menu" : "Open menu");
  veil.inert = !v;
  behind.forEach((el) => { el.inert = v; });
  if (v) {
    const at = links.findIndex((a) => a.getAttribute("aria-current") === "page");
    show(Math.max(0, at));
    setTimeout(() => { if (open && root.isConnected) links[Math.max(0, at)].focus({ preventScroll: true }); }, 260);
  } else if (returnFocus) {
    btn.focus({ preventScroll: true });
  }
}

btn.addEventListener("click", () => setOpen(!open, true));

links.forEach((a, i) => {
  a.addEventListener("pointerenter", () => show(i));
  a.addEventListener("focus", () => show(i));
  a.addEventListener("click", () => {
    links.forEach((l) => l.removeAttribute("aria-current"));
    a.setAttribute("aria-current", "page");
    setOpen(false, true);
  });
});

root.addEventListener("click", (e) => {
  const a = e.target.closest('a[href^="#"]');
  if (a) e.preventDefault();
});

root.addEventListener("keydown", (e) => {
  if (!open) return;
  if (e.key === "Escape") { e.preventDefault(); setOpen(false, true); return; }
  if (e.key === "Tab") {
    // keep focus inside the open menu: button + everything focusable in the veil
    const ring = [btn, ...veil.querySelectorAll("a[href], button")];
    const i = ring.indexOf(document.activeElement);
    if (e.shiftKey && i <= 0) { e.preventDefault(); ring[ring.length - 1].focus(); }
    else if (!e.shiftKey && i === ring.length - 1) { e.preventDefault(); ring[0].focus(); }
    return;
  }
  const li = links.indexOf(document.activeElement);
  if (li < 0) return;
  let n = -1;
  if (e.key === "ArrowDown") n = (li + 1) % links.length;
  else if (e.key === "ArrowUp") n = (li - 1 + links.length) % links.length;
  else if (e.key === "Home") n = 0;
  else if (e.key === "End") n = links.length - 1;
  if (n > -1) { e.preventDefault(); links[n].focus(); }
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  origin();
});
ro.observe(root);
origin();

