@property --bkn-morph-l { syntax: "<length>"; inherits: true; initial-value: 0px; }
@property --bkn-morph-r { syntax: "<length>"; inherits: true; initial-value: 0px; }
@property --bkn-morph-b { syntax: "<length>"; inherits: true; initial-value: 0px; }

.bkn-morph {
  --bkn-morph-paper: oklch(0.985 0.005 150);
  --bkn-morph-ink: oklch(0.23 0.025 165);
  --bkn-morph-accent: oklch(0.55 0.12 158);
  --bkn-morph-warn: oklch(0.7 0.15 65);
  --bkn-morph-muted: color-mix(in oklch, var(--bkn-morph-ink) 60%, var(--bkn-morph-paper));
  --bkn-morph-line: color-mix(in oklch, var(--bkn-morph-ink) 11%, transparent);
  --bkn-morph-tint: color-mix(in oklch, var(--bkn-morph-ink) 5%, transparent);
  --bkn-morph-wash: color-mix(in oklch, var(--bkn-morph-accent) 9%, var(--bkn-morph-paper));
  --bkn-morph-panel: oklch(1 0 none);
  --bkn-morph-ease: cubic-bezier(.22, .9, .24, 1);
  --bkn-morph-gut: clamp(16px, 4cqi, 48px);
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  width: 100%;
  min-height: 620px;
  background:
    repeating-linear-gradient(to bottom, transparent 0 31px, color-mix(in oklch, var(--bkn-morph-accent) 7%, transparent) 31px 32px),
    var(--bkn-morph-paper);
  color: var(--bkn-morph-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, p, ul, ol, li, dl, dd, figure, blockquote) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(a, button):focus-visible { outline: 2px solid var(--bkn-morph-accent); outline-offset: 2px; border-radius: 8px; }
  & svg { flex: none; }
}

.bkn-morph-bar {
  position: relative;
  z-index: 3;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-areas: "logo cta" "nav nav";
  align-items: center;
  row-gap: 6px;
  padding: 14px var(--bkn-morph-gut) 0;
  background: color-mix(in oklch, var(--bkn-morph-paper) 86%, transparent);
  border-bottom: 1px solid var(--bkn-morph-line);
}
.bkn-morph-logo {
  grid-area: logo;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  & svg { width: 26px; height: 26px; }
  & b { font-size: 18px; font-weight: 680; letter-spacing: -.03em; }
}
.bkn-morph-lg1 { fill: var(--bkn-morph-ink); }
.bkn-morph-lg2 { fill: var(--bkn-morph-accent); }
.bkn-morph-nav {
  grid-area: nav;
  margin-inline: calc(var(--bkn-morph-gut) * -1);
  padding-inline: calc(var(--bkn-morph-gut) - 10px);
  overflow-x: auto;
  scrollbar-width: none;
  &::-webkit-scrollbar { display: none; }
}
.bkn-morph-menu { display: flex; gap: 2px; padding-block: 4px 6px; }
.bkn-morph-top {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 38px;
  padding: 0 10px;
  border-radius: 9px;
  white-space: nowrap;
  font-size: 14.5px;
  font-weight: 520;
  color: color-mix(in oklch, var(--bkn-morph-ink) 78%, var(--bkn-morph-paper));
  transition: background-color .18s, color .18s;
  &:hover { color: var(--bkn-morph-ink); background: var(--bkn-morph-tint); }
  &:focus-visible { outline-offset: -2px; }
}
.bkn-morph-trig[aria-expanded="true"] { color: var(--bkn-morph-ink); background: var(--bkn-morph-tint); }
.bkn-morph-chev {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: .6;
  transition: rotate .35s var(--bkn-morph-ease);
  .bkn-morph-trig[aria-expanded="true"] & { rotate: 180deg; opacity: 1; }
}
.bkn-morph-cta {
  grid-area: cta;
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 6px;
}
.bkn-morph-signin { display: none; padding: 8px 12px; font-size: 14.5px; font-weight: 520; border-radius: 9px; &:hover { background: var(--bkn-morph-tint); } }
.bkn-morph-btn {
  display: inline-flex;
  align-items: center;
  height: 38px;
  padding: 0 16px;
  border-radius: 10px;
  background: var(--bkn-morph-ink);
  color: var(--bkn-morph-paper);
  font-size: 14.5px;
  font-weight: 600;
  letter-spacing: -.005em;
  box-shadow: inset 0 1px 0 color-mix(in oklch, white 18%, transparent), 0 1px 2px color-mix(in oklch, var(--bkn-morph-ink) 30%, transparent);
  transition: background-color .2s, translate .2s var(--bkn-morph-ease);
  &:hover { background: color-mix(in oklch, var(--bkn-morph-ink) 86%, var(--bkn-morph-accent)); }
  &:active { translate: 0 1px; }
}

/* ---------- the morphing stage ---------- */
.bkn-morph-stage {
  --bkn-morph-t: 10px;
  /* three registered edges, each with its own clock: the sides lead, the bottom follows */
  --bkn-morph-edges: --bkn-morph-l .5s var(--bkn-morph-ease), --bkn-morph-r .5s var(--bkn-morph-ease), --bkn-morph-b .46s var(--bkn-morph-ease) .05s;
  --bkn-morph-shape: inset(var(--bkn-morph-t) var(--bkn-morph-r) var(--bkn-morph-b) var(--bkn-morph-l) round 14px);
  position: absolute;
  inset: var(--bkn-morph-top, 116px) 0 0 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0;
  translate: 0 -8px;
  transition: opacity .16s ease-out, translate .25s ease-out, var(--bkn-morph-edges);
}
.bkn-morph.is-open .bkn-morph-stage {
  opacity: 1;
  translate: 0 0;
  transition: opacity .22s ease-out, translate .5s var(--bkn-morph-ease), var(--bkn-morph-edges);
}
.bkn-morph-shadow {
  position: absolute;
  inset: 0;
  opacity: .2;
  translate: 0 14px;
  filter: blur(16px);
  & i { position: absolute; inset: 0; background: var(--bkn-morph-ink); clip-path: var(--bkn-morph-shape); }
}
.bkn-morph-edge {
  position: absolute;
  inset: 0;
  background: color-mix(in oklch, var(--bkn-morph-ink) 12%, transparent);
  clip-path: inset(calc(var(--bkn-morph-t) - 1px) calc(var(--bkn-morph-r) - 1px) calc(var(--bkn-morph-b) - 1px) calc(var(--bkn-morph-l) - 1px) round 15px);
}
.bkn-morph-clip { position: absolute; inset: 0; clip-path: var(--bkn-morph-shape); }
.bkn-morph-bg {
  position: absolute;
  inset: 0;
  background: var(--bkn-morph-panel);
  .bkn-morph.is-open & { pointer-events: auto; }
}
.bkn-morph-caret {
  position: absolute;
  top: 4px;
  left: 0;
  width: 13px;
  height: 13px;
  border-radius: 3px 0 0 0;
  background: var(--bkn-morph-panel);
  box-shadow: -1px -1px 0 color-mix(in oklch, var(--bkn-morph-ink) 12%, transparent);
  translate: calc(var(--bkn-morph-cx, 0px) - 6.5px) 0;
  rotate: 45deg;
  transition: translate .5s var(--bkn-morph-ease);
}
.bkn-morph-stage.is-snap, .bkn-morph-stage.is-snap .bkn-morph-caret { transition: none; }

.bkn-morph-sect {
