  &.is-on { visibility: visible; opacity: 1; pointer-events: auto; transition: none; }
}
.bkn-morph-s0 { width: min(720px, 100cqi - 2 * var(--bkn-morph-gut)); display: grid; grid-template-columns: minmax(0, 1fr); gap: 4px; }
.bkn-morph-s1 { width: min(700px, 100cqi - 2 * var(--bkn-morph-gut)); display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 4px 8px; }
.bkn-morph-s2 { width: min(640px, 100cqi - 2 * var(--bkn-morph-gut)); display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px; }

.bkn-morph-item {
