  .bkn-morph-item:is(:hover, :focus-visible) & { background: var(--bkn-morph-accent); color: var(--bkn-morph-paper); scale: 1.06; }
}
.bkn-morph-tx {
  display: grid;
  gap: 1px;
  & b { font-size: 14.5px; font-weight: 600; letter-spacing: -.01em; }
  & small { font-size: 13px; line-height: 1.4; color: var(--bkn-morph-muted); text-wrap: pretty; }
