}
.bkn-morph-chip { position: absolute; top: 14px; left: 14px; width: 24px; height: 18px; border-radius: 4px; background: linear-gradient(135deg, oklch(0.88 0.08 85), oklch(0.72 0.08 75)); }
.bkn-morph-meter {
