  & i { display: inline-block; width: 7px; height: 7px; margin-right: 7px; border-radius: 50%; background: var(--bkn-morph-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--bkn-morph-accent) 20%, transparent); }
}
.bkn-morph-inv {
