  & .is-done i { background: var(--bkn-morph-accent); }
  & .is-now i { box-shadow: 0 0 0 4px color-mix(in oklch, var(--bkn-morph-accent) 18%, transparent); }
  & small { margin-left: auto; font-weight: 400; color: var(--bkn-morph-muted); font-size: 12px; }
}
.bkn-morph-sync {
  display: grid;
  & small { font-size: 11.5px; color: var(--bkn-morph-muted); font-family: ui-monospace, Menlo, monospace; }
  & b { font-size: 30px; font-weight: 680; letter-spacing: -.035em; line-height: 1.1; font-variant-numeric: tabular-nums; }
