}

.bkn-morph-h { padding: 8px 12px 4px; font-size: 11.5px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--bkn-morph-muted); }
.bkn-morph-row {
  justify-content: space-between;
  align-items: baseline;
  padding-block: 8px;
  font-size: 14.5px;
  font-weight: 540;
  & small { font-size: 12.5px; font-weight: 400; color: var(--bkn-morph-muted); font-variant-numeric: tabular-nums; }
}
.bkn-morph-badge { font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 999px; background: var(--bkn-morph-wash); color: var(--bkn-morph-accent); font-variant-numeric: tabular-nums; }
.bkn-morph-quote {
