  margin: 4px 2px 2px;
  padding: 14px 16px;
  border-radius: 10px;
  background: var(--bkn-morph-wash);
  & blockquote { font-size: 15px; font-weight: 520; letter-spacing: -.01em; text-wrap: balance; }
  & figcaption { margin-top: 6px; font-size: 12.5px; color: var(--bkn-morph-muted); }
  & b { color: var(--bkn-morph-ink); font-weight: 600; margin-right: 6px; }
}
.bkn-morph-feat {
  display: grid;
  gap: 2px;
  align-content: start;
  padding: 14px;
  background: var(--bkn-morph-wash);
  & svg { width: 100%; height: 64px; margin-bottom: 10px; }
  & rect { fill: color-mix(in oklch, var(--bkn-morph-accent) 32%, var(--bkn-morph-panel)); transform-box: fill-box; transform-origin: 50% 100%; transition: scale .5s var(--bkn-morph-ease); }
  & .bkn-morph-hi { fill: var(--bkn-morph-accent); }
  & .bkn-morph-base { stroke: var(--bkn-morph-line); stroke-width: 1.5; }
  & small { font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--bkn-morph-accent); }
  & b { font-size: 16px; font-weight: 650; letter-spacing: -.015em; }
  & span { font-size: 13px; line-height: 1.45; color: var(--bkn-morph-muted); text-wrap: pretty; }
  &:hover { background: color-mix(in oklch, var(--bkn-morph-accent) 14%, var(--bkn-morph-paper)); }
  &:hover rect:not(.bkn-morph-hi) { scale: 1 .9; }
}

/* ---------- hero ---------- */
.bkn-morph-hero {
  display: grid;
  justify-items: start;
  gap: 18px;
  padding: clamp(40px, 7cqi, 88px) var(--bkn-morph-gut) clamp(36px, 5cqi, 64px);
}
.bkn-morph-new {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px 4px 4px;
  border-radius: 999px;
  border: 1px solid var(--bkn-morph-line);
  background: var(--bkn-morph-panel);
  font-size: 13px;
  font-weight: 520;
  & span { padding: 2px 8px; border-radius: 999px; background: var(--bkn-morph-accent); color: var(--bkn-morph-paper); font-size: 11.5px; font-weight: 650; }
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; transition: translate .3s var(--bkn-morph-ease); }
  &:hover svg { translate: 3px 0; }
}
.bkn-morph-title {
  max-width: 14ch;
  font-size: clamp(38px, 5.6cqi + 14px, 76px);
  line-height: 1;
  font-weight: 680;
  letter-spacing: -.045em;
  text-wrap: balance;
}
.bkn-morph-lede { max-width: 48ch; font-size: clamp(15.5px, .5cqi + 13px, 18px); color: var(--bkn-morph-muted); text-wrap: pretty; }
.bkn-morph-ctas { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 4px; }
.bkn-morph-ctas .bkn-morph-btn { height: 46px; padding: 0 22px; font-size: 15.5px; }
.bkn-morph-ghost {
