  align-items: center;
  height: 46px;
  padding: 0 20px;
  border-radius: 10px;
  border: 1px solid var(--bkn-morph-line);
  background: var(--bkn-morph-panel);
  font-size: 15.5px;
  font-weight: 560;
  &:hover { border-color: color-mix(in oklch, var(--bkn-morph-ink) 25%, transparent); }
}
.bkn-morph-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, auto));
  gap: 0 clamp(18px, 4cqi, 56px);
  margin-top: clamp(12px, 3cqi, 32px);
  & div { display: flex; flex-direction: column-reverse; justify-content: flex-end; }
  & dt { font-size: 12.5px; color: var(--bkn-morph-muted); }
  & dd { font-size: clamp(22px, 1.8cqi + 14px, 32px); font-weight: 660; letter-spacing: -.035em; font-variant-numeric: tabular-nums; }
}

.bkn-morph-close {
  display: none;
  grid-area: card;
  align-self: center;
  justify-self: end;
  width: min(100%, 380px);
  padding: 20px;
  border: 1px solid var(--bkn-morph-line);
  border-radius: 18px;
  background: var(--bkn-morph-panel);
  box-shadow: 0 1px 2px color-mix(in oklch, var(--bkn-morph-ink) 8%, transparent), 0 24px 48px -24px color-mix(in oklch, var(--bkn-morph-ink) 30%, transparent);
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
}
.bkn-morph-ch { display: grid; align-content: center; & b { font-size: 16px; font-weight: 650; letter-spacing: -.015em; } & span { font-size: 12.5px; color: var(--bkn-morph-muted); } }
.bkn-morph-ring {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  border-radius: 50%;
