  .bkn-morph-new { grid-area: new; }
  .bkn-morph-title { grid-area: title; }
  .bkn-morph-lede { grid-area: lede; }
  .bkn-morph-ctas { grid-area: ctas; }
  .bkn-morph-stats { grid-area: stats; }
