  .bkn-morph-tx small { display: none; }
  .bkn-morph-s1 .bkn-morph-row small { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bkn-morph .bkn-morph-stage, .bkn-morph.is-open .bkn-morph-stage { translate: none; transition: opacity .15s linear; }
  .bkn-morph .bkn-morph-caret, .bkn-morph .bkn-morph-chev { transition: none; }
  .bkn-morph .bkn-morph-shot, .bkn-morph .bkn-morph-shot.is-on { translate: none; filter: none; transition: opacity .15s linear; }
  .bkn-morph .bkn-morph-ic, .bkn-morph .bkn-morph-feat rect { transition: none; scale: none; }
  .bkn-morph .bkn-morph-steps .is-now i { animation: none; }
}

