const bar = root.querySelector(".bkn-morph-bar");
const stage = root.querySelector(".bkn-morph-stage");
const trigs = [...root.querySelectorAll(".bkn-morph-trig")];
const tops = [...root.querySelectorAll(".bkn-morph-top")];
const sects = trigs.map((t) => root.querySelector("#" + t.getAttribute("aria-controls")));
const shots = [...root.querySelectorAll(".bkn-morph-shot")];
const reduce = matchMedia("(prefers-reduced-motion: reduce)");
const T = 10;               // gap between the bar and the panel, where the caret sits
let cur = -1, openT = 0, closeT = 0, hoverAt = 0, pv = 0;

function measureTop() {
  root.style.setProperty("--bkn-morph-top", (bar.offsetTop + bar.offsetHeight) + "px");
}

// The panel is one white layer the size of the whole stage, clipped to the
// active menu's rect through three registered <length> edges. Each edge
// transitions on its own, so the panel never squashes its corners the way a
// scaled box would, and the bottom can trail the sides by a beat.
function geom(i) {
  const R = root.getBoundingClientRect();
  const t = trigs[i].getBoundingClientRect();
  const w = sects[i].offsetWidth, h = sects[i].offsetHeight;
  const gut = Math.max(16, Math.min(48, R.width * 0.04));
  const cx = t.left + t.width / 2 - R.left;
  const left = Math.max(gut, Math.min(R.width - gut - w, cx - w / 2));
  return { left, w, h, cx, W: R.width, H: stage.clientHeight };
}
function shape(i, snap) {
  const g = geom(i);
  sects[i].style.translate = g.left + "px 0";
  if (snap) stage.classList.add("is-snap");
  stage.style.setProperty("--bkn-morph-l", g.left + "px");
  stage.style.setProperty("--bkn-morph-r", (g.W - g.left - g.w) + "px");
  stage.style.setProperty("--bkn-morph-b", Math.max(0, g.H - T - g.h) + "px");
  stage.style.setProperty("--bkn-morph-cx", Math.max(g.left + 18, Math.min(g.left + g.w - 18, g.cx)) + "px");
  if (snap) { stage.offsetWidth; stage.classList.remove("is-snap"); }
}

function open(i, focusFirst) {
  clearTimeout(closeT); clearTimeout(openT);
  if (i === cur) { if (focusFirst) items(i)[0].focus(); return; }
  const prev = cur;
  cur = i;
  trigs.forEach((t, k) => t.setAttribute("aria-expanded", String(k === i)));
  sects.forEach((s, k) => s.classList.toggle("is-on", k === i));
  if (prev < 0) {
    shape(i, true);
    root.classList.add("is-open");
    listenOutside(true);
  } else {
    shape(i, reduce.matches);
    if (!reduce.matches) {
      const d = i > prev ? 1 : -1;
      sects[prev].animate([{ opacity: 1, transform: "none" }, { opacity: 0, transform: "translateX(" + (-d * 56) + "px)" }],
        { duration: 220, easing: "cubic-bezier(.4,0,1,1)" });
      sects[i].animate([{ opacity: 0, transform: "translateX(" + (d * 56) + "px)" }, { opacity: 1, transform: "none" }],
        { duration: 480, easing: "cubic-bezier(.2,.9,.24,1)" });
    }
  }
  if (focusFirst) items(i)[0].focus();
}
function close(focusTrig) {
  clearTimeout(openT); clearTimeout(closeT);
  if (cur < 0) return;
  const i = cur;
  cur = -1;
  root.classList.remove("is-open");
  trigs.forEach((t) => t.setAttribute("aria-expanded", "false"));
  sects.forEach((s) => s.classList.remove("is-on"));
  listenOutside(false);
  if (focusTrig) trigs[i].focus();
}
const items = (i) => [...sects[i].querySelectorAll("a[href], button")];
const later = (ms) => { clearTimeout(closeT); closeT = setTimeout(() => close(false), ms); };

// Pointer: hover-intent opens, a short grace period lets the pointer cross the gap.
trigs.forEach((t, i) => {
  t.addEventListener("pointerenter", (e) => {
    if (e.pointerType !== "mouse") return;
    clearTimeout(closeT); clearTimeout(openT);
    if (cur >= 0) open(i);
    else openT = setTimeout(() => { open(i); hoverAt = performance.now(); }, 90);
  });
  t.addEventListener("pointerleave", (e) => { if (e.pointerType === "mouse") { clearTimeout(openT); later(240); } });
  t.addEventListener("click", () => {
    if (cur === i) { if (performance.now() - hoverAt > 450) close(false); }
    else open(i);
  });
});
root.querySelectorAll(".bkn-morph-link").forEach((a) =>
  a.addEventListener("pointerenter", (e) => { if (e.pointerType === "mouse" && cur >= 0) later(90); }));
stage.addEventListener("pointerover", () => clearTimeout(closeT));
stage.addEventListener("pointerout", (e) => {
  if (e.pointerType !== "mouse") return;
  const to = e.relatedTarget;
  if (to && to.closest && to.closest(".bkn-morph-sect.is-on, .bkn-morph-bg, .bkn-morph-trig")) return;
  later(240);
});

// Keyboard: arrows across the top row, into and through the open panel.
bar.addEventListener("keydown", (e) => {
  const k = tops.indexOf(document.activeElement);
  if (k < 0) return;
  const ti = trigs.indexOf(tops[k]);
  if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
    e.preventDefault();
    const n = tops[(k + (e.key === "ArrowRight" ? 1 : -1) + tops.length) % tops.length];
    n.focus();
    const ni = trigs.indexOf(n);
    if (cur >= 0) { if (ni >= 0) open(ni); else close(false); }
  } else if (e.key === "ArrowDown" && ti >= 0) {
    e.preventDefault(); open(ti, true);
  } else if (e.key === "Escape" && cur >= 0) {
    e.preventDefault(); close(true);
  } else if (e.key === "Tab" && !e.shiftKey && ti >= 0 && cur === ti) {
    // the panel lives after the bar in the DOM; step into it as if it followed its button
    e.preventDefault(); items(ti)[0].focus();
  }
});
stage.addEventListener("keydown", (e) => {
  if (cur < 0) return;
  const list = items(cur);
  const k = list.indexOf(document.activeElement);
  if (e.key === "Escape") { e.preventDefault(); close(true); return; }
  if (k < 0) return;
  let n = -1;
  if (e.key === "ArrowDown") n = (k + 1) % list.length;
  else if (e.key === "ArrowUp") n = (k - 1 + list.length) % list.length;
  else if (e.key === "Home") n = 0;
  else if (e.key === "End") n = list.length - 1;
  else if (e.key === "Tab" && e.shiftKey && k === 0) { e.preventDefault(); trigs[cur].focus(); return; }
  else if (e.key === "Tab" && !e.shiftKey && k === list.length - 1) {
    e.preventDefault();
    const next = tops[tops.indexOf(trigs[cur]) + 1];
    close(false);
    if (next) next.focus();
    return;
  }
  if (n > -1) { e.preventDefault(); list[n].focus(); }
});
root.addEventListener("focusout", (e) => {
  if (cur < 0) return;
  const to = e.relatedTarget;
  if (!to || !root.contains(to) || !(bar.contains(to) || stage.contains(to))) close(false);
});

// Preview pane follows the hovered or focused product.
root.querySelectorAll("[data-pv]").forEach((a) => {
  const go = () => {
    const n = +a.dataset.pv;
    if (n === pv) return;
    shots[pv].classList.remove("is-on");
    shots[n].classList.add("is-on");
    pv = n;
  };
  a.addEventListener("pointerenter", go);
  a.addEventListener("focus", go);
});

function onDoc(e) {
  if (!root.isConnected) { listenOutside(false); return; }
  if (!root.contains(e.target) || !(e.target.closest(".bkn-morph-bar") || e.target.closest(".bkn-morph-sect.is-on, .bkn-morph-bg"))) close(false);
}
function listenOutside(on) {
  if (on) document.addEventListener("pointerdown", onDoc, true);
  else document.removeEventListener("pointerdown", onDoc, true);
}

root.addEventListener("click", (e) => {
  const a = e.target.closest('a[href^="#"]');
  if (!a) return;
  e.preventDefault();
  if (stage.contains(a)) close(false);
});

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); listenOutside(false); return; }
  measureTop();
  if (cur >= 0) shape(cur, true);
});
ro.observe(root);
measureTop();

css:
.bkn-docs {
  --bkn-docs-bg: oklch(0.178 0.006 75);
  --bkn-docs-ink: oklch(0.94 0.008 85);
  --bkn-docs-accent: oklch(0.83 0.15 78);
  --bkn-docs-ok: oklch(0.79 0.15 152);
  --bkn-docs-muted: color-mix(in oklch, var(--bkn-docs-ink) 56%, var(--bkn-docs-bg));
  --bkn-docs-faint: color-mix(in oklch, var(--bkn-docs-ink) 34%, var(--bkn-docs-bg));
  --bkn-docs-line: color-mix(in oklch, var(--bkn-docs-ink) 10%, transparent);
  --bkn-docs-panel: color-mix(in oklch, var(--bkn-docs-ink) 4.5%, var(--bkn-docs-bg));
  --bkn-docs-raise: color-mix(in oklch, var(--bkn-docs-ink) 8%, var(--bkn-docs-bg));
  --bkn-docs-glow: color-mix(in oklch, var(--bkn-docs-accent) 16%, transparent);
  --bkn-docs-mono: ui-monospace, Menlo, Consolas, monospace;
  --bkn-docs-ease: cubic-bezier(.2, .9, .25, 1);
  --bkn-docs-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  --bkn-docs-gut: clamp(16px, 3.4cqi, 40px);
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  width: 100%;
  min-height: 560px;
  background: var(--bkn-docs-bg);
  color: var(--bkn-docs-ink);
  font: 400 14.5px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--bkn-docs-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, p, ul, li, pre) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(a, button, [tabindex]):focus-visible { outline: 2px solid var(--bkn-docs-accent); outline-offset: 2px; border-radius: 6px; }
  & kbd { font: 500 11px/1 var(--bkn-docs-mono); }
}

.bkn-docs-head {
  position: relative;
  z-index: 3;
  background: color-mix(in oklch, var(--bkn-docs-bg) 92%, black);
  border-bottom: 1px solid var(--bkn-docs-line);
}
.bkn-docs-row {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  grid-template-areas: "logo ver ." "search search search";
  align-items: center;
  gap: 10px 14px;
  padding: 12px var(--bkn-docs-gut) 10px;
}
.bkn-docs-logo {
  grid-area: logo;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkn-docs-accent); stroke-width: 1.7; stroke-linejoin: round; stroke-linecap: round; }
  & b { font: 650 17px/1 var(--bkn-docs-mono); letter-spacing: -.04em; }
  & span { padding: 3px 7px; border-radius: 5px; background: var(--bkn-docs-raise); color: var(--bkn-docs-muted); font: 500 11px/1 var(--bkn-docs-mono); letter-spacing: .04em; }
}

.bkn-docs-ver { grid-area: ver; position: relative; }
.bkn-docs-verbtn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  padding: 0 6px 0 9px;
  border: 1px solid var(--bkn-docs-line);
  border-radius: 7px;
  font: 500 12.5px/1 var(--bkn-docs-mono);
  color: var(--bkn-docs-muted);
  transition: color .15s, border-color .15s, background-color .15s;
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: rotate .3s var(--bkn-docs-ease); }
  &:hover, &[aria-expanded="true"] { color: var(--bkn-docs-ink); border-color: color-mix(in oklch, var(--bkn-docs-ink) 22%, transparent); background: var(--bkn-docs-panel); }
  &[aria-expanded="true"] svg { rotate: 180deg; }
  .bkn-docs.is-old & { color: var(--bkn-docs-accent); border-color: color-mix(in oklch, var(--bkn-docs-accent) 45%, transparent); }
}
.bkn-docs-vers {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 5;
  display: none;
  min-width: 168px;
  padding: 5px;
  border: 1px solid var(--bkn-docs-line);
  border-radius: 10px;
  background: var(--bkn-docs-raise);
  box-shadow: 0 16px 36px -12px black;
  opacity: 0;
  translate: 0 -4px;
  transition: opacity .12s, translate .12s, display .12s allow-discrete;
  &.is-open {
    display: block;
    opacity: 1;
    translate: 0 0;
    transition: opacity .18s, translate .3s var(--bkn-docs-ease), display .3s allow-discrete;
    @starting-style { opacity: 0; translate: 0 -6px; }
  }
  &:focus-visible { outline: none; }
  & li {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    padding: 7px 10px;
    border-radius: 6px;
    font: 500 12.5px/1.2 var(--bkn-docs-mono);
    cursor: pointer;
  }
  & li.is-active { background: var(--bkn-docs-glow); }
  & li[aria-selected="true"] { color: var(--bkn-docs-accent); }
  & li[aria-selected="true"]::after { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
  & small { margin-left: auto; color: var(--bkn-docs-faint); font-size: 10.5px; letter-spacing: .04em; }
  &:focus-visible li.is-active { outline: 1px solid color-mix(in oklch, var(--bkn-docs-accent) 60%, transparent); }
}

.bkn-docs-search { grid-area: search; position: relative; }
.bkn-docs-mag { position: absolute; left: 11px; top: 50%; translate: 0 -50%; width: 16px; height: 16px; fill: none; stroke: var(--bkn-docs-faint); stroke-width: 1.8; stroke-linecap: round; pointer-events: none; transition: stroke .15s; }
.bkn-docs-q {
  width: 100%;
  height: 38px;
  padding: 0 40px 0 35px;
  border: 1px solid var(--bkn-docs-line);
  border-radius: 9px;
  background: var(--bkn-docs-panel);
  color: var(--bkn-docs-ink);
  font: inherit;
  font-size: 14px;
  transition: border-color .15s, box-shadow .2s, background-color .15s;
  &::placeholder { color: var(--bkn-docs-faint); }
  &:hover { border-color: color-mix(in oklch, var(--bkn-docs-ink) 20%, transparent); }
  &:focus { outline: none; border-color: color-mix(in oklch, var(--bkn-docs-accent) 70%, transparent); box-shadow: 0 0 0 4px var(--bkn-docs-glow); background: var(--bkn-docs-raise); }
}
.bkn-docs-search:focus-within .bkn-docs-mag { stroke: var(--bkn-docs-accent); }
.bkn-docs-slash {
  position: absolute;
  right: 9px;
  top: 50%;
  translate: 0 -50%;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid var(--bkn-docs-line);
  border-radius: 5px;
  color: var(--bkn-docs-muted);
  pointer-events: none;
  transition: opacity .15s;
  .bkn-docs-search:focus-within & { opacity: 0; }
}

.bkn-docs-pop {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  z-index: 6;
  width: 100%;
  display: none;
  border: 1px solid var(--bkn-docs-line);
  border-radius: 12px;
  background: var(--bkn-docs-raise);
  box-shadow: 0 24px 48px -16px black, 0 0 0 1px color-mix(in oklch, black 40%, transparent);
  overflow: clip;
  opacity: 0;
  translate: 0 -4px;
  scale: .99;
  transform-origin: 50% 0;
  transition: opacity .12s, translate .12s, scale .12s, display .12s allow-discrete;
  .bkn-docs-search.is-open & {
    display: block;
    opacity: 1;
    translate: 0 0;
    scale: 1;
    transition: opacity .16s, translate .35s var(--bkn-docs-ease), scale .35s var(--bkn-docs-ease), display .35s allow-discrete;
    @starting-style { opacity: 0; translate: 0 -8px; scale: .985; }
  }
}
.bkn-docs-scroll {
  position: relative;
  max-height: 300px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 6px;
  scrollbar-width: thin;
  scrollbar-color: var(--bkn-docs-line) transparent;
}
.bkn-docs-hl {
  position: absolute;
  top: 0;
  left: 6px;
  right: 6px;
  height: 52px;
  border-radius: 8px;
  background: var(--bkn-docs-glow);
  box-shadow: inset 2px 0 0 var(--bkn-docs-accent);
  opacity: 0;
  pointer-events: none;
  transition: translate .38s var(--bkn-docs-spring), height .2s var(--bkn-docs-ease), opacity .15s;
}
.bkn-docs-opts { position: relative; }
.bkn-docs-grp {
  padding: 10px 10px 4px;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--bkn-docs-faint);
}
.bkn-docs-opt {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 8px;
  cursor: pointer;
  & b { display: block; font-weight: 560; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; font: 400 11.5px/1.3 var(--bkn-docs-mono); color: var(--bkn-docs-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & mark { background: none; color: var(--bkn-docs-accent); box-shadow: inset 0 -1.5px 0 color-mix(in oklch, var(--bkn-docs-accent) 55%, transparent); }
}
.bkn-docs-oi {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 7px;
  border: 1px solid var(--bkn-docs-line);
  color: var(--bkn-docs-muted);
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
}
.bkn-docs-ret {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: var(--bkn-docs-accent);
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
  opacity: 0;
  translate: -4px 0;
  transition: opacity .15s, translate .25s var(--bkn-docs-ease);
}
.bkn-docs-opt[aria-selected="true"] {
  & .bkn-docs-oi { color: var(--bkn-docs-accent); border-color: color-mix(in oklch, var(--bkn-docs-accent) 40%, transparent); }
  & .bkn-docs-ret { opacity: 1; translate: 0 0; }
}
.bkn-docs-empty {
  padding: 22px 12px;
  text-align: center;
  color: var(--bkn-docs-muted);
  font-size: 13.5px;
  text-wrap: balance;
  & b { color: var(--bkn-docs-ink); font-weight: 560; }
  & button { color: var(--bkn-docs-accent); text-decoration: underline; text-underline-offset: 3px; }
}
.bkn-docs-keys {
  display: flex;
  gap: 14px;
  padding: 9px 14px;
  border-top: 1px solid var(--bkn-docs-line);
  background: var(--bkn-docs-panel);
  font-size: 11.5px;
  color: var(--bkn-docs-faint);
  & span { display: inline-flex; align-items: center; gap: 4px; }
  & kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border: 1px solid var(--bkn-docs-line); border-radius: 4px; color: var(--bkn-docs-muted); font-size: 10.5px; }
  & .bkn-docs-count { margin-left: auto; font-family: var(--bkn-docs-mono); font-variant-numeric: tabular-nums; }
}

.bkn-docs-util {
  grid-area: util;
  display: none;
  justify-self: end;
  align-items: center;
  gap: 4px;
  & a { padding: 6px 10px; border-radius: 7px; font-size: 13.5px; color: var(--bkn-docs-muted); transition: color .15s, background-color .15s; }
  & a:hover { color: var(--bkn-docs-ink); background: var(--bkn-docs-panel); }
}
.bkn-docs-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  & i { position: relative; width: 7px; height: 7px; border-radius: 50%; background: var(--bkn-docs-ok); }
  & i::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: var(--bkn-docs-ok); animation: bkn-docs-ping 2.4s cubic-bezier(0, 0, .2, 1) infinite; }
}
@keyframes bkn-docs-ping { 0% { scale: 1; opacity: .7; } 70%, 100% { scale: 2.8; opacity: 0; } }

.bkn-docs-tabs {
  position: relative;
  display: flex;
  gap: 2px;
  padding: 0 calc(var(--bkn-docs-gut) - 10px);
  overflow-x: auto;
  scrollbar-width: none;
  &::-webkit-scrollbar { display: none; }
  & a {
    flex: none;
    padding: 10px 10px 12px;
    font-size: 13.5px;
    font-weight: 520;
    color: var(--bkn-docs-muted);
    transition: color .15s;
  }
  & a:hover, & a[aria-current="page"] { color: var(--bkn-docs-ink); }
  & a:focus-visible { outline-offset: -4px; }
}
.bkn-docs-ink {
  position: absolute;
  left: 0;
  bottom: -1px;
  width: 1px;
  height: 2px;
  background: var(--bkn-docs-accent);
  transform-origin: 0 0;
  transition: transform .45s var(--bkn-docs-ease);
}

/* ---------- the page behind ---------- */
.bkn-docs-page {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 32px;
  padding: clamp(22px, 3.6cqi, 40px) var(--bkn-docs-gut) 32px;
}
.bkn-docs-side { display: none; }
.bkn-docs-sideh { padding: 0 10px 8px; font-size: 11px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--bkn-docs-faint); }
.bkn-docs-sidelist {
  display: grid;
  gap: 1px;
  border-left: 1px solid var(--bkn-docs-line);
  & a { position: relative; display: block; padding: 5px 12px; font-size: 13.5px; color: var(--bkn-docs-muted); transition: color .15s; }
  & a:hover { color: var(--bkn-docs-ink); }
  & a[aria-current="page"] { color: var(--bkn-docs-accent); }
  & a[aria-current="page"]::before { content: ""; position: absolute; left: -1px; top: 6px; bottom: 6px; width: 2px; background: var(--bkn-docs-accent); }
}
.bkn-docs-art { display: grid; align-content: start; gap: 12px; max-width: 760px; &:focus { outline: none; } }
.bkn-docs-old {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  align-items: center;
  padding: 9px 12px;
  border: 1px solid color-mix(in oklch, var(--bkn-docs-accent) 35%, transparent);
  border-radius: 8px;
  background: var(--bkn-docs-glow);
  font-size: 13px;
  & b { font-family: var(--bkn-docs-mono); font-weight: 600; }
  & button { color: var(--bkn-docs-accent); font-weight: 560; text-decoration: underline; text-underline-offset: 3px; }
  &[hidden] { display: none; }
}
.bkn-docs-crumbs {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  color: var(--bkn-docs-faint);
  & svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .bkn-docs-c2 { color: var(--bkn-docs-muted); }
}
.bkn-docs-new { margin-left: 6px; padding: 2px 7px; border-radius: 999px; background: var(--bkn-docs-glow); color: var(--bkn-docs-accent); font: 600 10.5px/1.4 var(--bkn-docs-mono); &[hidden] { display: none; } }
.bkn-docs-title {
  font-size: clamp(28px, 2.6cqi + 16px, 40px);
  line-height: 1.1;
  font-weight: 680;
  letter-spacing: -.035em;
  text-wrap: balance;
  &:focus { outline: none; }
}
.bkn-docs-lede { max-width: 58ch; font-size: clamp(15px, .5cqi + 13px, 16.5px); color: var(--bkn-docs-muted); text-wrap: pretty; }
.bkn-docs-code {
  margin-top: 8px;
  padding: 16px 18px;
  border: 1px solid var(--bkn-docs-line);
  border-radius: 10px;
  background: color-mix(in oklch, var(--bkn-docs-bg) 70%, black);
  overflow-x: auto;
  font: 400 12.5px/1.7 var(--bkn-docs-mono);
  tab-size: 2;
  scrollbar-width: thin;
  & .k { color: var(--bkn-docs-accent); }
  & .s { color: oklch(0.82 0.1 150); }
  & .n { color: oklch(0.8 0.11 35); }
  & .c, & .p { color: var(--bkn-docs-faint); }
}

@container (min-width: 760px) {
  .bkn-docs-row {
    grid-template-columns: auto auto minmax(0, 420px) minmax(0, 1fr);
    grid-template-areas: "logo ver search util";
    padding-block: 12px;
    gap: 14px 18px;
  }
  .bkn-docs-util { display: flex; }
  .bkn-docs-pop { width: min(560px, 100cqi - 2 * var(--bkn-docs-gut)); }
  .bkn-docs-page { grid-template-columns: 200px minmax(0, 1fr); gap: clamp(24px, 4cqi, 56px); }
  .bkn-docs-side { display: block; }
}
@container (max-width: 420px) {
  .bkn-docs-keys span:nth-child(3) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .bkn-docs .bkn-docs-hl, .bkn-docs .bkn-docs-ink, .bkn-docs .bkn-docs-ret, .bkn-docs .bkn-docs-verbtn svg { transition: opacity .12s linear; }
  .bkn-docs .bkn-docs-pop, .bkn-docs .bkn-docs-search.is-open .bkn-docs-pop, .bkn-docs .bkn-docs-vers, .bkn-docs .bkn-docs-vers.is-open { translate: none; scale: none; transition: opacity .12s linear, display .12s allow-discrete; }
  .bkn-docs .bkn-docs-status i::after { animation: none; }
}

