const DATA = [
  { s: "Get started", t: "Installation", p: "/start/install", d: "Add Quarry to any Postgres 14+ database with a single migration." },
  { s: "Get started", t: "Your first job", p: "/start/first-job", d: "Define a handler, enqueue it, and watch a worker pick it up." },
  { s: "Get started", t: "Core concepts", p: "/start/concepts", d: "Queues, jobs, workers and leases, explained in five minutes." },
  { s: "Get started", t: "Upgrading from v2", p: "/start/upgrade-v2", d: "Rename three options, run one migration, keep every job in flight." },
  { s: "Guides", t: "Retry policies", p: "/guides/retries", d: "Exponential backoff, jitter and dead-letter queues for jobs that fail." },
  { s: "Guides", t: "Cron schedules", p: "/guides/cron", d: "Recurring jobs with cron syntax and timezone-aware run windows." },
  { s: "Guides", t: "Rate limiting", p: "/guides/rate-limits", d: "Cap throughput per queue, per tenant or per any key you choose." },
  { s: "Guides", t: "Priorities", p: "/guides/priorities", d: "Let urgent jobs jump the line without starving the rest." },
  { s: "Guides", t: "Idempotency keys", p: "/guides/idempotency", d: "Enqueue twice, run once, even across deploys." },
  { s: "Guides", t: "Batches", p: "/guides/batches", d: "Fan out ten thousand jobs and await them as one.", n: "v3.4" },
  { s: "Guides", t: "Graceful shutdown", p: "/guides/shutdown", d: "Drain workers on deploy without dropping a single lease." },
  { s: "Guides", t: "Observability", p: "/guides/metrics", d: "Export queue depth, wait time and failure rate to your metrics stack." },
  { s: "API reference", t: "quarry.enqueue()", p: "/api/enqueue", d: "Add a job to a queue. Resolves to a JobHandle." },
  { s: "API reference", t: "quarry.schedule()", p: "/api/schedule", d: "Register a recurring job from a cron expression." },
  { s: "API reference", t: "Worker", p: "/api/worker", d: "A long-running process that leases jobs and runs their handlers." },
  { s: "API reference", t: "JobHandle", p: "/api/job-handle", d: "Await, cancel or inspect a job after it has been enqueued." },
  { s: "API reference", t: "RetryPolicy", p: "/api/retry-policy", d: "Attempts, backoff curve and dead-letter target for a queue." },
  { s: "API reference", t: "QueueOptions", p: "/api/queue-options", d: "Concurrency, lease length, rate limits and priority defaults." },
  { s: "CLI", t: "quarry migrate", p: "/cli/migrate", d: "Create or upgrade the Quarry schema in your database." },
  { s: "CLI", t: "quarry worker", p: "/cli/worker", d: "Start a worker process from the command line." },
  { s: "CLI", t: "quarry inspect", p: "/cli/inspect", d: "Peek at queue depth, stuck leases and recent failures." },
  { s: "CLI", t: "quarry retry", p: "/cli/retry", d: "Re-run failed jobs by id, queue or time range." },
  { s: "Changelog", t: "v3.4 — Batches", p: "/changelog/3-4", d: "Batches are generally available, and shutdown drains 40% faster.", n: "v3.4" },
  { s: "Changelog", t: "v3.3 — Tenant rate limits", p: "/changelog/3-3", d: "Rate limits can now be keyed by tenant, with burst allowances." }
];
const ORDER = ["Guides", "API reference", "CLI", "Get started", "Changelog"];
const SUGGEST = ["/guides/retries", "/guides/cron", "/api/enqueue", "/cli/inspect"];
const RETRY = `import { Quarry } from "@quarry/client";

const quarry = new Quarry({ connection: process.env.DATABASE_URL });

await quarry.enqueue("send-invoice", { invoiceId: 4812 }, {
  attempts: 5,
  backoff: { type: "exponential", base: "2s", max: "10m" },
  deadLetter: "invoices-dlq",
});`;
const CODE = {
  "/guides/retries": RETRY,
  "/guides/cron": `await quarry.schedule("nightly-digest", "0 6 * * 1-5", {
  timezone: "Europe/Oslo",
  window: "15m", // start any time in the first 15 minutes
});`,
  "/guides/batches": `const batch = await quarry.batch("resize-image", photos.map((p) => ({ id: p.id })));

const { succeeded, failed } = await batch.done();
// succeeded: 9988  failed: 12  (10000 jobs)`,
  "/guides/rate-limits": `await quarry.queue("emails", {
  rateLimit: { per: "tenant", max: 120, window: "1m", burst: 20 },
});`,
  "/guides/idempotency": `await quarry.enqueue("charge-card", { orderId: 7731 }, {
  idempotencyKey: "order-7731-charge",
  keyTtl: "24h",
});`,
  "/api/schedule": `quarry.schedule(
  name: string,
  cron: string,
  options?: ScheduleOptions,
): Promise<Schedule>`,
  "/cli/retry": `$ quarry retry --queue invoices --since 2h
found 3 failed jobs
✓ 3 jobs re-enqueued with fresh leases`
};
const FALLBACK = {
  "Get started": `$ npm install @quarry/client
$ npx quarry migrate --database $DATABASE_URL
✓ schema quarry@3.4 applied in 0.8s`,
  "Guides": RETRY,
  "API reference": `quarry.enqueue(
  queue: string,
  payload: JsonValue,
  options?: EnqueueOptions,
): Promise<JobHandle>`,
  "CLI": `$ quarry inspect --queue invoices
queue      depth  running  failed  p95 wait
invoices     142        8       3      1.8s`,
  "Changelog": `+ quarry.batch() is generally available
+ workers drain 40% faster on SIGTERM
~ retry jitter now defaults to "full"`
};
const ICON = {
  "Get started": '<path d="M6 21V4M6 5h11l-2.5 4L17 13H6"/>',
  "Guides": '<path d="M5 5.5A2.5 2.5 0 0 1 7.5 3H19v15H7.5A2.5 2.5 0 0 0 5 20.5z"/><path d="M5 20.5V5.5M9 7.5h6"/>',
  "API reference": '<path d="M9 4c-2 0-3 1-3 3v2c0 1.5-1 2.5-2 3 1 .5 2 1.5 2 3v2c0 2 1 3 3 3M15 4c2 0 3 1 3 3v2c0 1.5 1 2.5 2 3-1 .5-2 1.5-2 3v2c0 2-1 3-3 3"/>',
  "CLI": '<path d="m5 7 5 5-5 5M12 18h7"/>',
  "Changelog": '<circle cx="12" cy="12" r="8"/><path d="M12 8v4l3 2"/>'
};
const SVGNS = "http://www.w3.org/2000/svg";

const box = root.querySelector(".bkn-docs-search");
const input = root.querySelector(".bkn-docs-q");
const scroller = root.querySelector(".bkn-docs-scroll");
const opts = root.querySelector(".bkn-docs-opts");
const hl = root.querySelector(".bkn-docs-hl");
const empty = root.querySelector(".bkn-docs-empty");
const count = root.querySelector(".bkn-docs-count");
const tabs = [...root.querySelectorAll(".bkn-docs-tabs a")];
const ink = root.querySelector(".bkn-docs-ink");
const side = root.querySelector(".bkn-docs-sidelist");
const sideH = root.querySelector(".bkn-docs-sideh");
const art = root.querySelector(".bkn-docs-art");
const title = root.querySelector(".bkn-docs-title");
const lede = root.querySelector(".bkn-docs-lede");
const c1 = root.querySelector(".bkn-docs-c1");
const c2 = root.querySelector(".bkn-docs-c2");
const isNew = root.querySelector(".bkn-docs-new");
const code = root.querySelector(".bkn-docs-code code");
const verBtn = root.querySelector(".bkn-docs-verbtn");
const verList = root.querySelector(".bkn-docs-vers");
const vers = [...verList.querySelectorAll("[role=option]")];
const old = root.querySelector(".bkn-docs-old");
const reduce = matchMedia("(prefers-reduced-motion: reduce)");

let results = [], active = -1, page = DATA[4], ver = "v3.4", verAt = 0;

// ---------- scoring: every word must land somewhere; titles weigh most ----------
const escRe = (w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const subseq = (t, w) => { let i = 0; for (const ch of t) if (ch === w[i]) i++; return i === w.length; };
function score(e, q) {
  const t = e.t.toLowerCase(), d = e.d.toLowerCase();
  let s = 0;
  for (const w of q.split(/\s+/).filter(Boolean)) {
    let ws = 0;
    if (t.startsWith(w)) ws = 12;
    else if (new RegExp("(^|[^a-z])" + escRe(w)).test(t)) ws = 9;
    else if (t.includes(w)) ws = 6;
    else if (e.p.includes(w)) ws = 4;
    else if (d.includes(w)) ws = 2;
    else if (w.length > 2 && subseq(t, w)) ws = 1;
    if (!ws) return 0;
    s += ws;
  }
  return s;
}
function marked(text, q) {
  const frag = document.createDocumentFragment();
  const words = q.split(/\s+/).filter(Boolean).sort((a, b) => b.length - a.length);
  const low = text.toLowerCase();
  let at = -1, len = 0;
  for (const w of words) { const k = low.indexOf(w); if (k > -1) { at = k; len = w.length; break; } }
  if (at < 0) { frag.append(text); return frag; }
  const m = document.createElement("mark");
  m.textContent = text.slice(at, at + len);
  frag.append(text.slice(0, at), m, text.slice(at + len));
  return frag;
}
function icon(sec) {
  const s = document.createElementNS(SVGNS, "svg");
  s.setAttribute("viewBox", "0 0 24 24");
  s.setAttribute("aria-hidden", "true");
  s.innerHTML = ICON[sec];
  return s;
}

function render() {
  const q = input.value.trim().toLowerCase();
  let list, groups;
  if (!q) {
    list = SUGGEST.map((p) => DATA.find((e) => e.p === p));
    groups = [["Suggested", list]];
  } else {
    list = DATA.map((e) => [score(e, q), e]).filter((x) => x[0] > 0).sort((a, b) => b[0] - a[0] || ORDER.indexOf(a[1].s) - ORDER.indexOf(b[1].s)).slice(0, 8).map((x) => x[1]);
    // groups appear in the order of their best hit, so the first option is always the top result
    const secs = [...new Set(list.map((e) => e.s))];
    groups = secs.map((s) => [s, list.filter((e) => e.s === s)]);
  }
  opts.textContent = "";
  results = [];
  groups.forEach(([name, rows], gi) => {
    const g = document.createElement("div");
    g.setAttribute("role", "group");
    const h = document.createElement("p");
    h.className = "bkn-docs-grp";
    h.id = "bkn-docs-g" + gi;
    h.textContent = name;
    g.setAttribute("aria-labelledby", h.id);
    g.append(h);
    rows.forEach((e) => {
      const o = document.createElement("div");
      o.className = "bkn-docs-opt";
      o.setAttribute("role", "option");
      o.id = "bkn-docs-o" + results.length;
      o.setAttribute("aria-selected", "false");
      const ic = document.createElement("span");
      ic.className = "bkn-docs-oi";
      ic.append(icon(e.s));
      const tx = document.createElement("span");
      const b = document.createElement("b");
      b.append(marked(e.t, q));
      const sm = document.createElement("small");
      sm.textContent = e.p;
      tx.append(b, sm);
      const ret = document.createElementNS(SVGNS, "svg");
      ret.setAttribute("viewBox", "0 0 16 16");
      ret.setAttribute("class", "bkn-docs-ret");
      ret.setAttribute("aria-hidden", "true");
      ret.innerHTML = '<path d="M13 3v5a2 2 0 0 1-2 2H3M6 7l-3 3 3 3"/>';
      o.append(ic, tx, ret);
      const k = results.length;
      o.addEventListener("pointermove", () => { if (active !== k) setActive(k); });
      o.addEventListener("pointerdown", (ev) => ev.preventDefault());
      o.addEventListener("click", () => go(e));
      g.append(o);
      results.push({ el: o, e });
    });
    opts.append(g);
  });
  empty.hidden = results.length > 0;
  if (!results.length) {
    empty.textContent = "";
    const b = document.createElement("b");
    b.textContent = "“" + input.value.trim() + "”";
    const tryBtn = document.createElement("button");
    tryBtn.type = "button";
    tryBtn.textContent = "retry";
    tryBtn.addEventListener("pointerdown", (ev) => ev.preventDefault());
    tryBtn.addEventListener("click", () => { input.value = "retry"; render(); });
    empty.append("Nothing matches ", b, ". Try ", tryBtn, " or a CLI command.");
  }
  count.textContent = q ? results.length + " of " + DATA.length + " pages" : DATA.length + " pages indexed";
  scroller.scrollTop = 0;
  setActive(results.length ? 0 : -1, true);
}

function setActive(i, instant) {
  active = i;
  results.forEach((r, k) => r.el.setAttribute("aria-selected", String(k === i)));
  if (i < 0) { input.removeAttribute("aria-activedescendant"); hl.style.opacity = "0"; return; }
  const o = results[i].el;
  input.setAttribute("aria-activedescendant", o.id);
  if (instant) hl.style.transition = "none";
  hl.style.translate = "0 " + o.offsetTop + "px";
  hl.style.height = o.offsetHeight + "px";
  hl.style.opacity = "1";
  if (instant) { hl.offsetWidth; hl.style.transition = ""; }
  // keep the active row in view without scrollIntoView, which would scroll the page too
  const top = o.offsetTop, bot = top + o.offsetHeight, pad = 30;
  if (top - pad < scroller.scrollTop) scroller.scrollTop = Math.max(0, top - pad);
  else if (bot + 6 > scroller.scrollTop + scroller.clientHeight) scroller.scrollTop = bot + 6 - scroller.clientHeight;
}

function openRes() {
  if (box.classList.contains("is-open")) return;
  closeVer(false);
  box.classList.add("is-open");
  input.setAttribute("aria-expanded", "true");
  render();
}
function closeRes() {
  box.classList.remove("is-open");
  input.setAttribute("aria-expanded", "false");
  input.removeAttribute("aria-activedescendant");
}

// ---------- the page below follows the result you pick ----------
function tokens(src) {
  const frag = document.createDocumentFragment();
  const re = /(\/\/.*$)|("(?:[^"\\]|\\.)*")|\b(import|from|const|await|new|async|return)\b|\b(\d[\d.]*[a-z%]*)\b|^(\$)/gm;
  let last = 0, m;
  while ((m = re.exec(src))) {
    if (m.index > last) frag.append(src.slice(last, m.index));
    const sp = document.createElement("span");
    sp.className = m[1] ? "c" : m[2] ? "s" : m[3] ? "k" : m[4] ? "n" : "p";
    sp.textContent = m[0];
    frag.append(sp);
    last = re.lastIndex;
  }
