box.addEventListener("focusout", (e) => { if (!box.contains(e.relatedTarget)) closeRes(); });

// "/" or Cmd/Ctrl+K from anywhere inside the component jumps to search
root.addEventListener("keydown", (e) => {
  const typing = e.target.closest("input, textarea, [contenteditable]");
