@property --bkn-solid-p { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --bkn-solid-f { syntax: "<number>"; inherits: true; initial-value: 0; }

.bkn-solid {
  --bkn-solid-paper: oklch(0.975 0.008 85);
  --bkn-solid-ink: oklch(0.25 0.03 225);
  --bkn-solid-ember: oklch(0.66 0.16 45);
  --bkn-solid-snow: oklch(0.99 0.004 85);
  --bkn-solid-muted: color-mix(in oklch, var(--bkn-solid-ink) 62%, var(--bkn-solid-paper));
  --bkn-solid-line: color-mix(in oklch, var(--bkn-solid-ink) 12%, transparent);
  --bkn-solid-card: color-mix(in oklch, var(--bkn-solid-paper) 60%, white);
  --bkn-solid-H: clamp(500px, 34cqi + 280px, 640px);
  --bkn-solid-navh: 64px;
  --bkn-solid-gut: clamp(16px, 4cqi, 48px);
  --bkn-solid-ease: cubic-bezier(.2, .9, .25, 1);
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  width: 100%;
  background: var(--bkn-solid-paper);
  color: var(--bkn-solid-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, p, ul, li, dl, dd) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(a, button):focus-visible { outline: 2px solid var(--bkn-solid-ember); outline-offset: 3px; border-radius: 6px; }
}

.bkn-solid-scroll {
  position: relative;
  height: var(--bkn-solid-H);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--bkn-solid-ink) 25%, transparent) transparent;
  &:focus-visible { outline: 2px solid var(--bkn-solid-ember); outline-offset: -2px; }
}

/* ---------- the nav: everything derives from one number, k ---------- */
.bkn-solid-nav {
  --bkn-solid-k: max(var(--bkn-solid-p), var(--bkn-solid-f));
  position: sticky;
  top: 0;
  z-index: 5;
  height: var(--bkn-solid-navh);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 0 var(--bkn-solid-gut);
  color: color-mix(in oklch, var(--bkn-solid-ink) calc(var(--bkn-solid-k) * 100%), var(--bkn-solid-snow));
  background: color-mix(in oklch, var(--bkn-solid-paper) calc(var(--bkn-solid-k) * 96%), transparent);
  box-shadow:
    0 1px 0 color-mix(in oklch, var(--bkn-solid-ink) calc(var(--bkn-solid-k) * 11%), transparent),
    0 12px 28px -20px color-mix(in oklch, var(--bkn-solid-ink) calc(var(--bkn-solid-k) * 50%), transparent);
  transition: --bkn-solid-f .4s var(--bkn-solid-ease);
  &::before {
    content: "";
    position: absolute;
    inset: 0 0 -24px;
    z-index: -1;
    pointer-events: none;
    background: linear-gradient(oklch(0.2 0.03 240 / .45), transparent);
    opacity: calc(1 - var(--bkn-solid-k));
  }
}
.bkn-solid-logo {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  & svg { width: 30px; height: 30px; }
  & span { font-size: 17px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; }
}
.bkn-solid-lm { fill: currentColor; }
.bkn-solid-ls { fill: color-mix(in oklch, var(--bkn-solid-ember) calc(var(--bkn-solid-k) * 100%), var(--bkn-solid-ink)); }
.bkn-solid-links {
  display: none;
  justify-self: center;
  gap: 4px;
  & a { position: relative; padding: 8px 12px; font-size: 14.5px; font-weight: 560; opacity: .86; transition: opacity .2s; }
  & a:hover, & a[aria-current="true"] { opacity: 1; }
  & a::after {
    content: "";
    position: absolute;
    left: 12px;
    right: 12px;
    bottom: 3px;
    height: 2px;
    border-radius: 2px;
    background: currentColor;
    scale: 0 1;
    transition: scale .45s var(--bkn-solid-ease);
  }
  & a[aria-current="true"]::after { scale: 1 1; }
}
.bkn-solid-cta {
  display: none;
  align-items: center;
  height: 38px;
  padding: 0 16px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 650;
  color: color-mix(in oklch, var(--bkn-solid-snow) calc(var(--bkn-solid-k) * 100%), var(--bkn-solid-snow));
  background: color-mix(in oklch, var(--bkn-solid-ember) calc(var(--bkn-solid-k) * 100%), transparent);
  box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--bkn-solid-snow) calc((1 - var(--bkn-solid-k)) * 80%), transparent);
  transition: translate .25s var(--bkn-solid-ease);
  &:hover { translate: 0 -1px; }
}
.bkn-solid-menu {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  margin-right: -8px;
  border-radius: 10px;
  & span { position: relative; width: 20px; height: 14px; }
  & i { position: absolute; left: 0; width: 100%; height: 2px; border-radius: 2px; background: currentColor; transition: translate .35s var(--bkn-solid-ease), rotate .35s var(--bkn-solid-ease), scale .25s; }
  & i:nth-child(1) { top: 0; }
  & i:nth-child(2) { top: 6px; }
  & i:nth-child(3) { top: 12px; }
}
.bkn-solid.is-menu .bkn-solid-nav { --bkn-solid-f: 1; }
.bkn-solid.is-menu .bkn-solid-menu {
  & i:nth-child(1) { translate: 0 6px; rotate: 45deg; }
  & i:nth-child(2) { scale: 0 1; }
  & i:nth-child(3) { translate: 0 -6px; rotate: -45deg; }
}
.bkn-solid-prog {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2px;
  background: var(--bkn-solid-ember);
  transform-origin: 0 50%;
  scale: var(--bkn-solid-q, 0) 1;
  opacity: var(--bkn-solid-p);
}
.bkn-solid-drawer {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  display: grid;
  padding: 8px var(--bkn-solid-gut) 20px;
  background: var(--bkn-solid-paper);
  color: var(--bkn-solid-ink);
  box-shadow: 0 24px 40px -24px color-mix(in oklch, var(--bkn-solid-ink) 50%, transparent);
  clip-path: inset(0 0 100% 0);
  visibility: hidden;
  transition: clip-path .4s cubic-bezier(.6, 0, .3, 1), visibility 0s .4s;
  & a {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 12px 0;
    border-bottom: 1px solid var(--bkn-solid-line);
    font-size: 22px;
    font-weight: 680;
    letter-spacing: -.02em;
    opacity: 0;
    translate: 0 -8px;
    transition: opacity .2s, translate .2s;
  }
  & small { font-size: 13px; font-weight: 450; letter-spacing: 0; color: var(--bkn-solid-muted); }
  & .bkn-solid-dcta { justify-content: center; margin-top: 14px; padding: 12px; border: 0; border-radius: 999px; background: var(--bkn-solid-ember); color: var(--bkn-solid-snow); font-size: 16px; }
}
.bkn-solid.is-menu .bkn-solid-drawer {
  clip-path: inset(0 0 -60px 0);
  visibility: visible;
  transition: clip-path .5s var(--bkn-solid-ease), visibility 0s;
  & a { opacity: 1; translate: 0 0; transition: opacity .4s calc(var(--i) * 45ms + 120ms), translate .5s var(--bkn-solid-ease) calc(var(--i) * 45ms + 120ms); }
}

/* ---------- hero ---------- */
.bkn-solid-hero {
  position: relative;
  height: calc(var(--bkn-solid-H) - 40px);
  margin-top: calc(var(--bkn-solid-navh) * -1);
  overflow: clip;
  color: var(--bkn-solid-snow);
  background: oklch(0.24 0.03 225);
}
.bkn-solid-layer { position: absolute; inset: 0; width: 100%; height: 100%; }
.bkn-solid-far { translate: 0 calc(var(--bkn-solid-y, 0) * .38px); }
.bkn-solid-mid { translate: 0 calc(var(--bkn-solid-y, 0) * .22px); }
.bkn-solid-sky { translate: 0 calc(var(--bkn-solid-y, 0) * .5px); }
.bkn-solid-copy {
  position: relative;
  display: grid;
  justify-items: start;
  gap: 14px;
  padding: calc(var(--bkn-solid-navh) + clamp(28px, 6cqi, 80px)) var(--bkn-solid-gut) 0;
  max-width: 720px;
  translate: 0 calc(var(--bkn-solid-y, 0) * .25px);
  opacity: calc(1 - var(--bkn-solid-y, 0) / 420);
}
.bkn-solid-kick { font-size: 12px; font-weight: 650; letter-spacing: .16em; text-transform: uppercase; opacity: .85; }
.bkn-solid-h {
  font-size: clamp(36px, 5.4cqi + 14px, 74px);
  line-height: .98;
  font-weight: 760;
  letter-spacing: -.04em;
  text-wrap: balance;
  text-shadow: 0 2px 30px oklch(0.2 0.03 240 / .35);
}
.bkn-solid-sub { max-width: 42ch; font-size: clamp(15px, .5cqi + 13px, 17.5px); opacity: .9; text-wrap: pretty; }
.bkn-solid-btn {
  margin-top: 6px;
  display: inline-flex;
  align-items: center;
  height: 46px;
  padding: 0 22px;
  border-radius: 999px;
  background: var(--bkn-solid-snow);
  color: var(--bkn-solid-ink);
  font-weight: 650;
  transition: translate .25s var(--bkn-solid-ease), box-shadow .25s;
  &:hover { translate: 0 -2px; box-shadow: 0 10px 24px -12px black; }
}
.bkn-solid-hint {
  position: absolute;
  left: 50%;
  bottom: 18px;
  translate: -50% 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 999px;
  background: oklch(0.2 0.03 240 / .35);
  backdrop-filter: blur(6px);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; animation: bkn-solid-nudge 1.8s cubic-bezier(.45, 0, .55, 1) infinite; }
}
@keyframes bkn-solid-nudge { 0%, 100% { translate: 0 -1px; } 50% { translate: 0 3px; } }

/* ---------- page content ---------- */
.bkn-solid-sec {
  display: grid;
  gap: 22px;
  padding: clamp(40px, 6cqi, 72px) var(--bkn-solid-gut) 8px;
  scroll-margin-top: var(--bkn-solid-navh);
}
.bkn-solid-head {
  display: grid;
  gap: 10px;
  & h2 { max-width: 20ch; font-size: clamp(26px, 2.8cqi + 14px, 42px); line-height: 1.05; font-weight: 740; letter-spacing: -.035em; text-wrap: balance; }
  & p:not(.bkn-solid-eyebrow) { max-width: 46ch; color: var(--bkn-solid-muted); text-wrap: pretty; }
}
.bkn-solid-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--bkn-solid-ember); }
.bkn-solid-cards { display: grid; gap: 14px; }
.bkn-solid-card {
  position: relative;
  display: grid;
  gap: 10px;
  padding: 18px 18px 22px;
  border: 1px solid var(--bkn-solid-line);
  border-radius: 16px;
  background: var(--bkn-solid-card);
  overflow: clip;
  & h3 { font-size: 21px; font-weight: 720; letter-spacing: -.025em; }
  & dl { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); padding-top: 10px; border-top: 1px solid var(--bkn-solid-line); }
  & dl div { display: flex; flex-direction: column-reverse; justify-content: flex-end; }
  & dt { font-size: 11.5px; color: var(--bkn-solid-muted); }
  & dd { font-size: 16px; font-weight: 680; font-variant-numeric: tabular-nums; }
}
.bkn-solid-region { font-size: 12px; font-weight: 600; color: var(--bkn-solid-muted); }
.bkn-solid-prof {
  width: 100%;
  height: 44px;
  & path { fill: none; stroke: var(--bkn-solid-ink); stroke-width: 1.6; vector-effect: non-scaling-stroke; stroke-linejoin: round; }
}
.bkn-solid-price {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  & b { font-size: 15px; font-weight: 700; font-variant-numeric: tabular-nums; }
  & span { font-size: 12.5px; color: var(--bkn-solid-ember); font-weight: 600; font-variant-numeric: tabular-nums; }
}
.bkn-solid-fill {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--bkn-solid-ember) calc(var(--v) * 100%), var(--bkn-solid-line) 0);
}
.bkn-solid-huts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  & li { display: inline-flex; gap: 8px; align-items: baseline; padding: 8px 14px; border-radius: 999px; background: var(--bkn-solid-card); border: 1px solid var(--bkn-solid-line); font-weight: 600; font-size: 14px; }
  & span { font-size: 12px; font-weight: 500; color: var(--bkn-solid-muted); font-variant-numeric: tabular-nums; }
  & .bkn-solid-more { background: none; border-style: dashed; color: var(--bkn-solid-muted); font-weight: 500; }
}
.bkn-solid-people {
  display: grid;
  gap: 10px;
  & li { display: grid; grid-template-columns: 44px 1fr; grid-template-rows: auto auto; column-gap: 12px; align-items: center; }
  & b { font-size: 15.5px; font-weight: 680; align-self: end; }
  & small { grid-column: 2; font-size: 13px; color: var(--bkn-solid-muted); align-self: start; }
}
.bkn-solid-av {
  grid-row: span 2;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: color-mix(in oklch, var(--bkn-solid-ember) 18%, var(--bkn-solid-paper));
  color: color-mix(in oklch, var(--bkn-solid-ember) 70%, var(--bkn-solid-ink));
  font-size: 13px;
  font-weight: 750;
  letter-spacing: .04em;
}
.bkn-solid-posts a {
  display: grid;
  gap: 2px;
  padding: 14px 0;
  border-bottom: 1px solid var(--bkn-solid-line);
  font-size: 17px;
  font-weight: 650;
  letter-spacing: -.015em;
  & small { font-size: 12.5px; font-weight: 500; color: var(--bkn-solid-muted); }
  &:hover { color: var(--bkn-solid-ember); }
}
.bkn-solid-foot { padding: 40px var(--bkn-solid-gut) 28px; font-size: 12.5px; color: var(--bkn-solid-muted); }

/* ---------- scroll-driven: the browser animates p; JS only steps in without support ---------- */
@keyframes bkn-solid-solidify { from { --bkn-solid-p: 0; } to { --bkn-solid-p: 1; } }
@keyframes bkn-solid-grow { from { scale: 0 1; } to { scale: 1 1; } }
@keyframes bkn-solid-drift-sky { to { translate: 0 calc(var(--bkn-solid-H) * .5); } }
@keyframes bkn-solid-drift-far { to { translate: 0 calc(var(--bkn-solid-H) * .38); } }
@keyframes bkn-solid-drift-mid { to { translate: 0 calc(var(--bkn-solid-H) * .22); } }
@keyframes bkn-solid-drift-copy { to { translate: 0 calc(var(--bkn-solid-H) * .25); opacity: 0; } }
@keyframes bkn-solid-hide { to { opacity: 0; translate: -50% 12px; } }
@supports (animation-timeline: scroll()) {
  .bkn-solid-nav {
    animation: bkn-solid-solidify linear both;
    animation-timeline: scroll(nearest block);
    animation-range: calc(var(--bkn-solid-H) - 300px) calc(var(--bkn-solid-H) - 110px);
  }
  .bkn-solid-prog { animation: bkn-solid-grow linear both; animation-timeline: scroll(nearest block); }
  .bkn-solid-sky { animation: bkn-solid-drift-sky linear both; animation-timeline: scroll(nearest block); animation-range: 0 var(--bkn-solid-H); }
  .bkn-solid-far { animation: bkn-solid-drift-far linear both; animation-timeline: scroll(nearest block); animation-range: 0 var(--bkn-solid-H); }
  .bkn-solid-mid { animation: bkn-solid-drift-mid linear both; animation-timeline: scroll(nearest block); animation-range: 0 var(--bkn-solid-H); }
  .bkn-solid-copy { animation: bkn-solid-drift-copy linear both; animation-timeline: scroll(nearest block); animation-range: 0 calc(var(--bkn-solid-H) * .8); }
  .bkn-solid-hint { animation: bkn-solid-hide linear both; animation-timeline: scroll(nearest block); animation-range: 0 90px; }
}

@container (min-width: 720px) {
  .bkn-solid-links { display: flex; }
  .bkn-solid-cta { display: inline-flex; }
  .bkn-solid-menu, .bkn-solid-drawer { display: none; }
  .bkn-solid-cards { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .bkn-solid-split { grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr); align-items: start; column-gap: 6cqi; }
}
.bkn-solid-links { grid-column: 2; }
.bkn-solid-menu, .bkn-solid-cta { grid-column: 3; grid-row: 1; }

@media (prefers-reduced-motion: reduce) {
  .bkn-solid .bkn-solid-sky, .bkn-solid .bkn-solid-far, .bkn-solid .bkn-solid-mid, .bkn-solid .bkn-solid-copy { animation: none; translate: none; opacity: 1; }
  .bkn-solid .bkn-solid-hint svg { animation: none; }
  .bkn-solid .bkn-solid-drawer, .bkn-solid.is-menu .bkn-solid-drawer { transition: visibility 0s; clip-path: none; }
  .bkn-solid .bkn-solid-drawer a, .bkn-solid.is-menu .bkn-solid-drawer a { translate: none; transition: opacity .15s linear; }
  .bkn-solid .bkn-solid-links a::after, .bkn-solid .bkn-solid-menu i { transition: none; }
}

