const sc = root.querySelector(".bkn-solid-scroll");
const nav = root.querySelector(".bkn-solid-nav");
const hero = root.querySelector(".bkn-solid-hero");
const menu = root.querySelector(".bkn-solid-menu");
const drawer = root.querySelector(".bkn-solid-drawer");
const links = [...root.querySelectorAll(".bkn-solid-links a, .bkn-solid-drawer a[data-to]")];
const secs = [...root.querySelectorAll("[data-sec]")];
const reduce = matchMedia("(prefers-reduced-motion: reduce)");
const native = window.CSS && CSS.supports("animation-timeline: scroll()");

// Fallback for engines without scroll timelines: write the same numbers the
// CSS animations would have produced, once per frame at most.
if (!native) {
  let raf = 0;
  const update = () => {
    if (!root.isConnected) return;
    raf = 0;
    const y = sc.scrollTop;
    const end = hero.offsetHeight - nav.offsetHeight + 0;
    const start = end - 190;
    const p = Math.min(1, Math.max(0, (y - start) / (end - start)));
    const max = Math.max(1, sc.scrollHeight - sc.clientHeight);
    nav.style.setProperty("--bkn-solid-p", p.toFixed(3));
    sc.style.setProperty("--bkn-solid-q", (y / max).toFixed(4));
    if (!reduce.matches) sc.style.setProperty("--bkn-solid-y", Math.min(y, hero.offsetHeight).toFixed(1));
  };
  sc.addEventListener("scroll", () => { if (!raf) raf = requestAnimationFrame(update); }, { passive: true });
  update();
}

// Scroll-spy, rooted on the component's own scroller: whichever block holds the
// reading line (35% down) wins; the hero means "no section yet".
const inBand = new Set();
const blocks = [hero, ...secs];
const io = new IntersectionObserver((entries) => {
  if (!root.isConnected) { io.disconnect(); return; }
  entries.forEach((en) => { if (en.isIntersecting) inBand.add(en.target); else inBand.delete(en.target); });
  const cur = blocks.filter((b) => inBand.has(b)).pop();
  if (!cur) return;
  const id = cur === hero ? "" : cur.dataset.sec;
  links.forEach((a) => { if (a.dataset.to === id) a.setAttribute("aria-current", "true"); else a.removeAttribute("aria-current"); });
}, { root: sc, rootMargin: "-35% 0px -60% 0px" });
blocks.forEach((b) => io.observe(b));

function setMenu(open, focus) {
  root.classList.toggle("is-menu", open);
  menu.setAttribute("aria-expanded", String(open));
  menu.setAttribute("aria-label", open ? "Close menu" : "Open menu");
  drawer.inert = !open;
  if (open && focus) setTimeout(() => { if (root.isConnected) drawer.querySelector("a").focus({ preventScroll: true }); }, 120);
  if (!open && focus) menu.focus({ preventScroll: true });
}
menu.addEventListener("click", () => setMenu(!root.classList.contains("is-menu"), true));
nav.addEventListener("focusout", (e) => {
  if (root.classList.contains("is-menu") && !nav.contains(e.relatedTarget)) setMenu(false, false);
});
root.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && root.classList.contains("is-menu")) { e.preventDefault(); setMenu(false, true); }
});

// In-page links scroll the component's scroller, never the host page.
root.addEventListener("click", (e) => {
  const a = e.target.closest('a[href^="#"]');
  if (!a) return;
  e.preventDefault();
  const to = a.dataset.to || (a.getAttribute("href") === "#top" ? "top" : "");
  if (!to) return;
  const target = to === "top" ? 0 : secs.find((s) => s.dataset.sec === to).offsetTop - nav.offsetHeight + 1;
  if (root.classList.contains("is-menu")) setMenu(false, false);
  sc.scrollTo({ top: target, behavior: reduce.matches ? "auto" : "smooth" });
});

