.bkn-ribbon {
  --bkn-ribbon-cream: oklch(0.975 0.022 92);
  --bkn-ribbon-plum: oklch(0.29 0.06 10);
  --bkn-ribbon-tomato: oklch(0.65 0.19 35);
  --bkn-ribbon-butter: oklch(0.91 0.12 98);
  --bkn-ribbon-leaf: oklch(0.6 0.13 140);
  --bkn-ribbon-mint: color-mix(in oklch, var(--bkn-ribbon-leaf) 30%, var(--bkn-ribbon-cream));
  --bkn-ribbon-peach: color-mix(in oklch, var(--bkn-ribbon-tomato) 30%, var(--bkn-ribbon-cream));
  --bkn-ribbon-lilac: oklch(0.86 0.06 320);
  --bkn-ribbon-muted: color-mix(in oklch, var(--bkn-ribbon-plum) 66%, var(--bkn-ribbon-cream));
  --bkn-ribbon-line: color-mix(in oklch, var(--bkn-ribbon-plum) 14%, transparent);
  --bkn-ribbon-round: ui-rounded, "SF Pro Rounded", "Arial Rounded MT Bold", system-ui, sans-serif;
  --bkn-ribbon-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067 22.4%, 1.084 25.1%, 1.077 28.8%, 1.038 34.4%, 1.006 40.6%, .99 47.7%, .995 63.1%, 1);
  --bkn-ribbon-soft: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  --bkn-ribbon-gut: clamp(16px, 4cqi, 48px);
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  width: 100%;
  min-height: 600px;
  background: var(--bkn-ribbon-cream);
  color: var(--bkn-ribbon-plum);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--bkn-ribbon-tomato);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, p, fieldset, legend) { margin: 0; padding: 0; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(a, button):focus-visible { outline: 2.5px solid var(--bkn-ribbon-tomato); outline-offset: 2px; border-radius: 10px; }
}

/* ---------- announcement ribbon ---------- */
.bkn-ribbon-ann {
  position: relative;
  z-index: 1;
  background: var(--bkn-ribbon-plum);
  color: var(--bkn-ribbon-cream);
  .bkn-ribbon.is-leaving & { position: absolute; inset: 0 0 auto 0; }
  .bkn-ribbon.is-gone & { display: none; }
}
.bkn-ribbon-annin {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto auto;
  align-items: center;
  gap: 4px;
  height: 42px;
  padding: 0 calc(var(--bkn-ribbon-gut) - 8px);
}
.bkn-ribbon-step, .bkn-ribbon-x {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  color: color-mix(in oklch, var(--bkn-ribbon-cream) 70%, transparent);
  transition: background-color .15s, color .15s;
  &:hover { background: color-mix(in oklch, var(--bkn-ribbon-cream) 12%, transparent); color: var(--bkn-ribbon-cream); }
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &:focus-visible { outline-color: var(--bkn-ribbon-butter); }
}
.bkn-ribbon-step[data-d="1"] { grid-column: 3; }
.bkn-ribbon-msgs {
  grid-column: 2;
  grid-row: 1;
  display: grid;
  height: 42px;
  overflow: clip;
}
.bkn-ribbon-msg {
  grid-area: 1 / 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-width: 0;
  font-size: 13.5px;
  font-weight: 520;
  white-space: nowrap;
  translate: 0 calc(var(--d, 1) * 110%);
  opacity: 0;
  transition: translate .6s var(--bkn-ribbon-soft), opacity .3s;
  &.is-on { translate: 0 0; opacity: 1; }
  &.is-out { translate: 0 calc(var(--d, 1) * -110%); opacity: 0; transition: translate .32s cubic-bezier(.5, 0, .75, 0), opacity .22s; }
  & a { font-weight: 700; color: var(--bkn-ribbon-butter); text-decoration: underline; text-decoration-thickness: 1.5px; text-underline-offset: 3px; }
  & a:hover { text-decoration-style: wavy; }
  & a:focus-visible { outline-color: var(--bkn-ribbon-butter); }
}
.bkn-ribbon-mi { width: 17px; height: 17px; flex: none; fill: none; stroke: var(--bkn-ribbon-butter); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.bkn-ribbon-short { display: none; }
.bkn-ribbon-long, .bkn-ribbon-short { overflow: hidden; text-overflow: ellipsis; }
.bkn-ribbon-cd {
  padding: 1px 7px;
  border-radius: 6px;
  background: color-mix(in oklch, var(--bkn-ribbon-butter) 18%, transparent);
  color: var(--bkn-ribbon-butter);
  font: 650 12.5px/1.5 ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
}
.bkn-ribbon-dots { grid-column: 4; display: none; gap: 5px; padding: 0 8px; }
.bkn-ribbon-dot {
  position: relative;
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 6px;
  overflow: clip;
  background: color-mix(in oklch, var(--bkn-ribbon-cream) 30%, transparent);
  transition: width .45s var(--bkn-ribbon-soft);
  & b { position: absolute; inset: 0; background: var(--bkn-ribbon-butter); transform-origin: 0 50%; scale: 0 1; }
  &.is-on { width: 24px; }
  &.is-on b { animation: bkn-ribbon-fill 6s linear forwards; }
}
@keyframes bkn-ribbon-fill { to { scale: 1 1; } }
.bkn-ribbon:is(.is-hold, .is-off) .bkn-ribbon-dot.is-on b { animation-play-state: paused; }
.bkn-ribbon-x { grid-column: 5; }

/* ---------- nav ---------- */
.bkn-ribbon-nav {
  position: relative;
  z-index: 3;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  padding: 14px var(--bkn-ribbon-gut);
  background: var(--bkn-ribbon-cream);
  border-bottom: 2px solid var(--bkn-ribbon-plum);
}
.bkn-ribbon-logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  & svg { width: 36px; height: 36px; transition: rotate .6s var(--bkn-ribbon-spring); }
  &:hover svg { rotate: -14deg; }
  & span { font: 800 22px/1 var(--bkn-ribbon-round); letter-spacing: -.03em; }
  & i { margin: 0 2px; font-style: normal; color: var(--bkn-ribbon-tomato); }
}
.bkn-ribbon-fruit { fill: var(--bkn-ribbon-butter); stroke: var(--bkn-ribbon-plum); stroke-width: 2; }
.bkn-ribbon-seg { fill: none; stroke: var(--bkn-ribbon-plum); stroke-width: 1.4; stroke-linecap: round; opacity: .35; }
.bkn-ribbon-leaf { fill: var(--bkn-ribbon-leaf); }
.bkn-ribbon-links {
  display: none;
  justify-self: center;
  gap: 6px;
  & a { position: relative; padding: 8px 12px; font: 750 15.5px/1.2 var(--bkn-ribbon-round); letter-spacing: -.01em; border-radius: 999px; transition: background-color .2s, rotate .4s var(--bkn-ribbon-spring); }
  & a:hover { background: var(--bkn-ribbon-butter); rotate: -2deg; }
  & a[aria-current="page"] { color: var(--bkn-ribbon-tomato); }
}
.bkn-ribbon-sq {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 1px;
  width: calc(100% - 24px);
  height: 6px;
  overflow: visible;
  & path { fill: none; stroke: var(--bkn-ribbon-tomato); stroke-width: 2.2; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1; opacity: 0; vector-effect: non-scaling-stroke; transition: stroke-dashoffset .5s cubic-bezier(.6, 0, .2, 1), opacity 0s .5s; }
  a:is(:hover, :focus-visible, [aria-current="page"]) > & path { stroke-dashoffset: 0; opacity: 1; transition: stroke-dashoffset .5s cubic-bezier(.6, 0, .2, 1), opacity 0s; }
}
.bkn-ribbon-tools { grid-column: 3; display: flex; align-items: center; gap: 2px; }
.bkn-ribbon-ic {
  position: relative;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  transition: background-color .15s, rotate .4s var(--bkn-ribbon-spring);
  &:hover { background: color-mix(in oklch, var(--bkn-ribbon-butter) 70%, transparent); }
  & svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}
.bkn-ribbon-acct { display: none; }
.bkn-ribbon-count {
  position: absolute;
  top: 2px;
  right: 1px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  border: 2px solid var(--bkn-ribbon-cream);
  background: var(--bkn-ribbon-tomato);
  color: var(--bkn-ribbon-cream);
  font: 800 10.5px/14px var(--bkn-ribbon-round);
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.bkn-ribbon-news {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 32px;
  margin-right: 4px;
  padding: 0 10px 0 8px;
  border-radius: 999px;
  background: var(--bkn-ribbon-plum);
  color: var(--bkn-ribbon-cream);
  font: 800 12px/1 var(--bkn-ribbon-round);
  scale: 1;
  opacity: 1;
  transition: scale .55s var(--bkn-ribbon-spring), opacity .2s, display .3s allow-discrete;
  @starting-style { scale: .4; opacity: 0; }
  &[hidden] { display: none; scale: .4; opacity: 0; }
  & svg { width: 16px; height: 16px; fill: none; stroke: var(--bkn-ribbon-butter); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; transform-origin: 50% 15%; animation: bkn-ribbon-ring 1.2s cubic-bezier(.36, .07, .19, .97) .3s 2; }
}
@keyframes bkn-ribbon-ring { 0%, 100% { rotate: 0deg; } 15% { rotate: 16deg; } 30% { rotate: -14deg; } 45% { rotate: 9deg; } 60% { rotate: -6deg; } 75% { rotate: 2deg; } }
.bkn-ribbon-burger {
  & path { transition: translate .4s var(--bkn-ribbon-soft), rotate .4s var(--bkn-ribbon-soft); transform-box: fill-box; transform-origin: center; }
  &[aria-expanded="true"] .bkn-ribbon-b1 { translate: 0 3.5px; rotate: 45deg; }
  &[aria-expanded="true"] .bkn-ribbon-b2 { translate: 0 -3.5px; rotate: -45deg; }
}
.bkn-ribbon-sheet {
  position: absolute;
  top: calc(100% + 8px);
  right: var(--bkn-ribbon-gut);
  left: var(--bkn-ribbon-gut);
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  padding: 8px;
  border: 2px solid var(--bkn-ribbon-plum);
  border-radius: 22px;
  background: var(--bkn-ribbon-cream);
  box-shadow: 6px 6px 0 var(--bkn-ribbon-plum);
  transform-origin: calc(100% - 20px) 0;
  visibility: hidden;
  opacity: 0;
  scale: .86;
  transition: scale .25s cubic-bezier(.5, 0, .75, 0), opacity .2s, visibility 0s .25s;
  & a { display: grid; gap: 2px; padding: 16px 14px; border-radius: 14px; background: var(--c); opacity: 0; translate: 0 10px; transition: opacity .15s, translate .2s; }
  & b { font: 800 18px/1.15 var(--bkn-ribbon-round); letter-spacing: -.02em; }
  & small { font-size: 12.5px; color: var(--bkn-ribbon-muted); }
  .bkn-ribbon.is-menu & {
    visibility: visible;
    opacity: 1;
    scale: 1;
    transition: scale .6s var(--bkn-ribbon-spring), opacity .2s, visibility 0s;
  }
  .bkn-ribbon.is-menu & a { opacity: 1; translate: 0 0; transition: opacity .3s calc(var(--i) * 50ms + 80ms), translate .55s var(--bkn-ribbon-spring) calc(var(--i) * 50ms + 80ms); }
}

/* ---------- hero ---------- */
.bkn-ribbon-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  padding: clamp(28px, 5cqi, 64px) var(--bkn-ribbon-gut) clamp(28px, 4cqi, 48px);
}
.bkn-ribbon-copy { display: grid; justify-items: start; gap: 16px; align-content: center; }
.bkn-ribbon-kick {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 560;
  color: var(--bkn-ribbon-muted);
  & span { padding: 3px 10px; border-radius: 999px; background: var(--bkn-ribbon-leaf); color: var(--bkn-ribbon-cream); font: 800 12px/1.3 var(--bkn-ribbon-round); rotate: -3deg; }
}
.bkn-ribbon-h {
  max-width: 13ch;
  font: 850 clamp(38px, 5.2cqi + 16px, 72px)/.95 var(--bkn-ribbon-round);
  letter-spacing: -.045em;
  text-wrap: balance;
}
.bkn-ribbon-lede { max-width: 40ch; font-size: clamp(15px, .4cqi + 13.5px, 17px); color: var(--bkn-ribbon-muted); text-wrap: pretty; }
.bkn-ribbon-sizes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  width: min(100%, 460px);
  & legend { margin-bottom: 8px; font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--bkn-ribbon-muted); }
  & label { position: relative; display: block; cursor: pointer; }
  & input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }
  & span { display: grid; gap: 1px; padding: 10px 12px; border: 2px solid var(--bkn-ribbon-line); border-radius: 14px; background: color-mix(in oklch, white 50%, var(--bkn-ribbon-cream)); transition: border-color .2s, background-color .2s, translate .4s var(--bkn-ribbon-spring), box-shadow .2s; }
  & b { font: 800 15px/1.2 var(--bkn-ribbon-round); }
  & small { font-size: 12px; color: var(--bkn-ribbon-muted); }
  & em { font: 800 14px/1.3 var(--bkn-ribbon-round); font-style: normal; color: var(--bkn-ribbon-tomato); font-variant-numeric: tabular-nums; }
  & label:hover span { border-color: color-mix(in oklch, var(--bkn-ribbon-plum) 35%, transparent); }
  & label:has(:checked) span { border-color: var(--bkn-ribbon-plum); background: var(--bkn-ribbon-butter); translate: 0 -3px; box-shadow: 0 3px 0 var(--bkn-ribbon-plum); }
  & label:has(:focus-visible) span { outline: 2.5px solid var(--bkn-ribbon-tomato); outline-offset: 2px; }
}
.bkn-ribbon-add {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 52px;
  padding: 0 14px 0 22px;
  border-radius: 999px;
  background: var(--bkn-ribbon-tomato);
  color: var(--bkn-ribbon-cream);
  font: 800 16px/1 var(--bkn-ribbon-round);
  box-shadow: 0 4px 0 var(--bkn-ribbon-plum);
  transition: translate .15s, box-shadow .15s, background-color .3s;
  & svg { width: 28px; height: 28px; padding: 5px; border-radius: 50%; background: var(--bkn-ribbon-cream); fill: none; stroke: var(--bkn-ribbon-tomato); stroke-width: 2.4; stroke-linecap: round; transition: rotate .5s var(--bkn-ribbon-spring), stroke .3s; }
  &:hover svg { rotate: 90deg; }
  &:active { translate: 0 3px; box-shadow: 0 1px 0 var(--bkn-ribbon-plum); }
  &.is-done { background: var(--bkn-ribbon-leaf); }
  &.is-done svg { stroke: var(--bkn-ribbon-leaf); rotate: 45deg; }
}
.bkn-ribbon-art { position: relative; justify-self: center; width: min(100%, 440px); }
.bkn-ribbon-crate { display: block; width: 100%; height: auto; }
.bkn-ribbon-stamp {
  position: absolute;
  top: 2%;
  right: 2%;
  width: 26%;
  animation: bkn-ribbon-spin 24s linear infinite;
  .bkn-ribbon.is-off & { animation-play-state: paused; }
}
@keyframes bkn-ribbon-spin { to { rotate: 360deg; } }

@container (min-width: 560px) {
  .bkn-ribbon-dots { display: flex; }
  .bkn-ribbon-acct { display: grid; }
}
@container (max-width: 559px) {
  .bkn-ribbon-long { display: none; }
  .bkn-ribbon-short { display: inline; }
  .bkn-ribbon-msg { font-size: 12.5px; gap: 6px; }
