@container (min-width: 860px) {
  .bkn-ribbon-links { display: flex; grid-column: 2; }
  .bkn-ribbon-burger, .bkn-ribbon-sheet { display: none; }
  .bkn-ribbon-hero { grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); align-items: center; column-gap: 4cqi; }
