  .bkn-ribbon .bkn-ribbon-dot.is-on b { animation: none; scale: 1 1; }
  .bkn-ribbon .bkn-ribbon-dot { transition: none; }
  .bkn-ribbon .bkn-ribbon-stamp, .bkn-ribbon .bkn-ribbon-news svg { animation: none; }
  .bkn-ribbon .bkn-ribbon-sheet, .bkn-ribbon.is-menu .bkn-ribbon-sheet { scale: none; transition: opacity .15s linear, visibility 0s; }
  .bkn-ribbon .bkn-ribbon-sheet a, .bkn-ribbon.is-menu .bkn-ribbon-sheet a { translate: none; transition: opacity .15s linear; }
  .bkn-ribbon .bkn-ribbon-news { transition: none; }
  .bkn-ribbon :is(.bkn-ribbon-links a, .bkn-ribbon-logo svg, .bkn-ribbon-sizes span, .bkn-ribbon-add svg) { transition: none; rotate: none; }
}

