const reduce = matchMedia("(prefers-reduced-motion: reduce)");
const SPRING = getComputedStyle(root).getPropertyValue("--bkn-ribbon-soft").trim() || "cubic-bezier(.2,.9,.25,1)";
const ann = root.querySelector(".bkn-ribbon-ann");
const live = root.querySelector(".bkn-ribbon-msgs");
const msgs = [...root.querySelectorAll(".bkn-ribbon-msg")];
const dots = [...root.querySelectorAll(".bkn-ribbon-dot")];
const nav = root.querySelector(".bkn-ribbon-nav");
const hero = root.querySelector(".bkn-ribbon-hero");
const xBtn = root.querySelector(".bkn-ribbon-x");
const news = root.querySelector(".bkn-ribbon-news");
const burger = root.querySelector(".bkn-ribbon-burger");
const sheet = root.querySelector(".bkn-ribbon-sheet");
const cart = root.querySelector(".bkn-ribbon-cart");
const count = root.querySelector(".bkn-ribbon-count");
const add = root.querySelector(".bkn-ribbon-add");
const addT = root.querySelector(".bkn-ribbon-addt");
const cds = [...root.querySelectorAll(".bkn-ribbon-cd")];
let cur = 0, items = 1, doneT = 0;

// radio groups are document-global by name; give this instance its own
const uid = "bkn-ribbon-size-" + Math.random().toString(36).slice(2, 8);
root.querySelectorAll('input[name="bkn-ribbon-size"]').forEach((r) => { r.name = uid; });

// ---------- ticker: CSS owns the clock, JS only reacts ----------
function show(n, d) {
  n = (n + msgs.length) % msgs.length;
  if (n === cur) return;
  const inc = msgs[n], out = msgs[cur];
  inc.style.transition = "none";
  inc.style.setProperty("--d", d);
  inc.classList.remove("is-out");
  inc.offsetWidth;
  inc.style.transition = "";
  out.style.setProperty("--d", d);
  out.classList.remove("is-on");
  out.classList.add("is-out");
  inc.classList.add("is-on");
  msgs.forEach((m) => { m.inert = m !== inc; });
  dots.forEach((dot, k) => dot.classList.toggle("is-on", k === n));
  cur = n;
}
dots.forEach((dot) => dot.querySelector("b").addEventListener("animationend", () => {
  if (!reduce.matches) show(cur + 1, 1);
}));
root.querySelectorAll(".bkn-ribbon-step").forEach((b) => b.addEventListener("click", () => {
  live.setAttribute("aria-live", "polite");
  show(cur + +b.dataset.d, +b.dataset.d);
}));
ann.addEventListener("pointerenter", () => root.classList.add("is-hold"));
ann.addEventListener("pointerleave", () => { if (!ann.contains(document.activeElement)) root.classList.remove("is-hold"); });
ann.addEventListener("focusin", () => root.classList.add("is-hold"));
ann.addEventListener("focusout", (e) => { if (!ann.contains(e.relatedTarget)) { root.classList.remove("is-hold"); live.setAttribute("aria-live", "off"); } });
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.classList.toggle("is-off", !es[es.length - 1].isIntersecting);
});
io.observe(root);

// ---------- countdown to the Friday 6 pm order cut-off ----------
function cutoff() {
  const now = new Date();
  const t = new Date(now);
  t.setHours(18, 0, 0, 0);
  t.setDate(now.getDate() + ((5 - now.getDay() + 7) % 7));
  if (t <= now) t.setDate(t.getDate() + 7);
  return t;
}
let end = cutoff();
const pad = (v) => String(v).padStart(2, "0");
function tick() {
  if (!root.isConnected) { clearInterval(iv); return; }
  if (document.hidden) return;
  let s = Math.floor((end - Date.now()) / 1000);
  if (s <= 0) { end = cutoff(); s = Math.floor((end - Date.now()) / 1000); }
  const d = Math.floor(s / 86400), h = Math.floor(s / 3600) % 24, m = Math.floor(s / 60) % 60;
  const txt = (d ? d + "d " : "") + pad(h) + ":" + pad(m) + ":" + pad(s % 60);
  cds.forEach((el) => { el.textContent = txt; });
}
const iv = setInterval(tick, 1000);
tick();

// ---------- dismiss and restore: FLIP the nav and hero into place ----------
function flip(firsts, dur) {
  [nav, hero].forEach((el, k) => {
    const dy = firsts[k] - el.getBoundingClientRect().top;
    if (dy) el.animate([{ transform: "translateY(" + dy + "px)" }, { transform: "none" }], { duration: dur, easing: SPRING });
  });
}
xBtn.addEventListener("click", () => {
  const firsts = [nav.getBoundingClientRect().top, hero.getBoundingClientRect().top];
  const done = () => {
    root.classList.remove("is-leaving");
    root.classList.add("is-gone");
    news.hidden = false;
    news.focus({ preventScroll: true });
  };
  if (reduce.matches) { done(); return; }
  root.classList.add("is-leaving");
  flip(firsts, 700);
  const a = ann.animate([{ opacity: 1, transform: "none" }, { opacity: 0, transform: "translateY(-40%)" }],
    { duration: 280, easing: "cubic-bezier(.5,0,.8,.3)", fill: "forwards" });
  a.onfinish = () => { done(); a.cancel(); };
});
news.addEventListener("click", () => {
  const firsts = [nav.getBoundingClientRect().top, hero.getBoundingClientRect().top];
  root.classList.remove("is-gone");
  news.hidden = true;
  xBtn.focus({ preventScroll: true });
  if (reduce.matches) return;
  flip(firsts, 700);
  ann.animate([{ opacity: 0, transform: "translateY(-40%)" }, { opacity: 1, transform: "none" }],
    { duration: 520, delay: 80, easing: SPRING, fill: "backwards" });
});

// ---------- menu sheet (narrow) ----------
function setMenu(open, focus) {
  root.classList.toggle("is-menu", open);
  burger.setAttribute("aria-expanded", String(open));
  burger.setAttribute("aria-label", open ? "Close menu" : "Open menu");
  sheet.inert = !open;
  if (open && focus) setTimeout(() => { if (root.isConnected) sheet.querySelector("a").focus({ preventScroll: true }); }, 90);
  if (!open && focus) burger.focus({ preventScroll: true });
}
burger.addEventListener("click", () => setMenu(!root.classList.contains("is-menu"), true));
root.addEventListener("keydown", (e) => { if (e.key === "Escape" && root.classList.contains("is-menu")) { e.preventDefault(); setMenu(false, true); } });
root.addEventListener("focusout", (e) => {
  if (root.classList.contains("is-menu") && !nav.contains(e.relatedTarget)) setMenu(false, false);
});

// ---------- box size and cart ----------
function label() {
  const r = root.querySelector('input[name="' + uid + '"]:checked');
  addT.textContent = "Add " + r.value + " box · $" + r.dataset.p;
}
root.querySelectorAll('input[name="' + uid + '"]').forEach((r) => r.addEventListener("change", () => {
  add.classList.remove("is-done");
  label();
}));
add.addEventListener("click", () => {
  items += 1;
  count.textContent = items;
  cart.setAttribute("aria-label", "Cart, " + items + " items");
  const r = root.querySelector('input[name="' + uid + '"]:checked');
  addT.textContent = r.value + " box added";
  add.classList.add("is-done");
  clearTimeout(doneT);
  doneT = setTimeout(() => { if (root.isConnected) { add.classList.remove("is-done"); label(); } }, 1600);
  if (!reduce.matches) {
    count.animate([{ scale: 1 }, { scale: 1.5 }, { scale: 1 }], { duration: 520, easing: "cubic-bezier(.3,1.6,.5,1)" });
    cart.animate([{ rotate: "0deg" }, { rotate: "-12deg" }, { rotate: "9deg" }, { rotate: "0deg" }], { duration: 460, easing: "ease-in-out" });
  }
});

root.addEventListener("click", (e) => {
  const a = e.target.closest('a[href^="#"]');
  if (!a) return;
  e.preventDefault();
  if (sheet.contains(a)) setMenu(false, true);
});

css:
.bkn-slab {
  --bkn-slab-paper: oklch(0.955 0.014 95);
  --bkn-slab-ink: oklch(0.18 0 0);
  --bkn-slab-pink: oklch(0.7 0.22 358);
  --bkn-slab-blue: oklch(0.55 0.15 255);
  --bkn-slab-sun: oklch(0.92 0.16 102);
  --bkn-slab-rule: 2.5px solid var(--bkn-slab-ink);
  --bkn-slab-wash: color-mix(in oklch, var(--bkn-slab-ink) 7%, var(--bkn-slab-paper));
  --bkn-slab-mono: ui-monospace, Menlo, Consolas, monospace;
  --bkn-slab-gut: clamp(16px, 3cqi, 32px);
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  width: 100%;
  min-height: 620px;
  display: grid;
  grid-template-rows: auto 1fr;
  background: var(--bkn-slab-paper);
  color: var(--bkn-slab-ink);
  border-block: var(--bkn-slab-rule);
  font: 500 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h3, p, ul, li, dl, dd) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(a, button):focus-visible { outline: 3px solid var(--bkn-slab-blue); outline-offset: -3px; }
}

/* ---------- bar: one row of ruled cells ---------- */
.bkn-slab-bar {
  position: relative;
  z-index: 3;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "logo bag" "nav nav";
  background: var(--bkn-slab-paper);
  border-bottom: var(--bkn-slab-rule);
}
.bkn-slab-logo {
  grid-area: logo;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px var(--bkn-slab-gut);
  border-right: var(--bkn-slab-rule);
  & svg { width: 40px; height: 40px; flex: none; }
  & span { font: 900 17px/.95 system-ui, sans-serif; letter-spacing: -.02em; text-transform: uppercase; }
}
.bkn-slab-lp { fill: var(--bkn-slab-pink); mix-blend-mode: multiply; }
.bkn-slab-lb { fill: var(--bkn-slab-blue); mix-blend-mode: multiply; transition: translate .3s steps(3, end); }
.bkn-slab-lk { stroke: var(--bkn-slab-ink); stroke-width: 3; }
.bkn-slab-logo:hover .bkn-slab-lb { translate: -3px 2px; }
.bkn-slab-nav { grid-area: nav; border-top: var(--bkn-slab-rule); }
.bkn-slab-menu {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  & li:nth-child(odd) { border-right: var(--bkn-slab-rule); }
  & li:nth-child(-n + 2) { border-bottom: var(--bkn-slab-rule); }
}
.bkn-slab-top {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  height: 56px;
  padding: 0 var(--bkn-slab-gut);
  font: 850 15px/1 system-ui, sans-serif;
  letter-spacing: .03em;
  text-transform: uppercase;
  text-align: left;
  transition: color .16s steps(2, end);
  &::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    background: var(--bkn-slab-ink);
    transform-origin: 50% 100%;
    scale: 1 0;
    transition: scale .2s steps(4, end);
  }
  &:hover { color: var(--bkn-slab-paper); }
  &:hover::before { scale: 1 1; }
  & sup { font: 600 10.5px/1 var(--bkn-slab-mono); letter-spacing: 0; text-transform: none; padding: 3px 5px; border: 1.5px solid currentColor; }
  &[aria-expanded="true"] { color: var(--bkn-slab-ink); }
  &[aria-expanded="true"]::before { scale: 1 1; background: var(--bkn-slab-pink); }
}
.bkn-slab-plus {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.6;
  transition: rotate .2s steps(3, end);
  [aria-expanded="true"] > & { rotate: 45deg; }
}
.bkn-slab-bag {
  grid-area: bag;
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 var(--bkn-slab-gut);
  font: 850 15px/1 system-ui, sans-serif;
  text-transform: uppercase;
  letter-spacing: .03em;
  & b { display: grid; place-items: center; min-width: 30px; height: 30px; padding: 0 6px; overflow: clip; background: var(--bkn-slab-sun); border: 2px solid var(--bkn-slab-ink); font: 700 14px/1 var(--bkn-slab-mono); font-variant-numeric: tabular-nums; }
  & i { font-style: normal; display: block; }
  &:hover b { background: var(--bkn-slab-pink); }
}

/* ---------- dropdowns ---------- */
.bkn-slab-drop {
  position: absolute;
  top: var(--bkn-slab-top, 128px);
  left: var(--bkn-slab-x, 16px);
  z-index: 4;
  width: min(780px, 100cqi - 2 * var(--bkn-slab-gut));
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  background: var(--bkn-slab-paper);
  border: var(--bkn-slab-rule);
  border-top: 0;
  box-shadow: 0 0 0 var(--bkn-slab-ink);
  visibility: hidden;
  clip-path: inset(0 -18px 100% -4px);
  transition: clip-path .24s steps(4, end), box-shadow .1s steps(1, end), visibility 0s .24s;
  &.is-on {
    visibility: visible;
    clip-path: inset(0 -18px -18px -4px);
    box-shadow: 10px 10px 0 var(--bkn-slab-ink);
    transition: clip-path .3s steps(6, end), box-shadow .16s steps(2, end) .3s, visibility 0s;
  }
}
.bkn-slab-list { display: grid; align-content: start; }
.bkn-slab-row {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "b em" "s em";
  align-items: center;
  column-gap: 12px;
  padding: 12px 16px;
  border-bottom: 2px solid var(--bkn-slab-ink);
  & b { grid-area: b; font-size: 15.5px; font-weight: 850; letter-spacing: -.01em; }
  & span { grid-area: s; font-size: 13px; font-weight: 500; color: color-mix(in oklch, var(--bkn-slab-ink) 68%, var(--bkn-slab-paper)); }
  & em { grid-area: em; font: 600 12.5px/1 var(--bkn-slab-mono); font-style: normal; font-variant-numeric: tabular-nums; padding: 5px 7px; border: 1.5px solid var(--bkn-slab-ink); }
  &::before { content: ""; position: absolute; inset: 0; z-index: -1; background: var(--bkn-slab-sun); transform-origin: 0 50%; scale: 0 1; transition: scale .18s steps(4, end); }
  &:is(:hover, :focus-visible)::before { scale: 1 1; }
  &:is(:hover, :focus-visible) em { background: var(--bkn-slab-ink); color: var(--bkn-slab-sun); }
}
.bkn-slab-all b { text-transform: uppercase; letter-spacing: .02em; }
.bkn-slab-card {
  display: grid;
  gap: 10px;
  align-content: start;
  padding: 16px;
  background: var(--bkn-slab-wash);
}
.bkn-slab-tag { justify-self: start; padding: 4px 7px; background: var(--bkn-slab-ink); color: var(--bkn-slab-paper); font: 600 11px/1 var(--bkn-slab-mono); letter-spacing: .06em; text-transform: uppercase; }
.bkn-slab-big {
  display: flex;
  align-items: baseline;
  gap: 8px;
  & b { font-size: 56px; line-height: .9; font-weight: 900; letter-spacing: -.05em; font-variant-numeric: tabular-nums; }
  & span { font: 600 13px/1.3 var(--bkn-slab-mono); }
}
.bkn-slab-meter {
  height: 22px;
  border: 2px solid var(--bkn-slab-ink);
  background: var(--bkn-slab-paper);
  & i { display: block; height: 100%; width: calc(var(--v) * 100%); background: repeating-linear-gradient(-45deg, var(--bkn-slab-ink) 0 4px, var(--bkn-slab-pink) 4px 9px); border-right: 2px solid var(--bkn-slab-ink); }
}
.bkn-slab-fine { font: 500 12.5px/1.45 var(--bkn-slab-mono); }
.bkn-slab-btn {
  justify-self: start;
  display: inline-flex;
  align-items: center;
  height: 40px;
  padding: 0 16px;
  border: 2.5px solid var(--bkn-slab-ink);
  background: var(--bkn-slab-sun);
  font: 850 14px/1 system-ui, sans-serif;
  text-transform: uppercase;
  letter-spacing: .03em;
  box-shadow: 4px 4px 0 var(--bkn-slab-ink);
  transition: translate .08s steps(1, end), box-shadow .08s steps(1, end), background-color .1s steps(1, end);
  &:hover { background: var(--bkn-slab-pink); }
  &:active { translate: 4px 4px; box-shadow: 0 0 0 var(--bkn-slab-ink); }
  &:focus-visible { outline-offset: 3px; }
  &.is-done { background: var(--bkn-slab-ink); color: var(--bkn-slab-sun); }
}
.bkn-slab-feat {
  grid-template-columns: 112px minmax(0, 1fr);
  column-gap: 16px;
  & h3 { font-size: 20px; line-height: 1.05; font-weight: 900; letter-spacing: -.03em; text-wrap: balance; }
}
.bkn-slab-fbody { display: grid; gap: 8px; align-content: start; }
.bkn-slab-buy { display: flex; align-items: center; gap: 14px; margin-top: 4px; & b { font-size: 24px; font-weight: 900; font-variant-numeric: tabular-nums; } }
.bkn-slab-cover {
  width: 100%;
  height: auto;
  border: 2px solid var(--bkn-slab-ink);
  box-shadow: 5px 5px 0 var(--bkn-slab-ink);
  rotate: -2deg;
  transition: rotate .24s steps(3, end);
}
.bkn-slab-cpaper { fill: oklch(0.97 0.01 90); }
.bkn-slab-ink1, .bkn-slab-ink2 { mix-blend-mode: multiply; transition: translate .24s steps(3, end); }
.bkn-slab-ink1 { fill: var(--bkn-slab-pink); stroke: var(--bkn-slab-pink); }
.bkn-slab-ink2 { fill: var(--bkn-slab-blue); stroke: var(--bkn-slab-blue); }
.bkn-slab-ctitle { font: 900 15px/1 system-ui, sans-serif; letter-spacing: -.02em; fill: var(--bkn-slab-blue); mix-blend-mode: multiply; }
.bkn-slab-cfoot { font: 600 7px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; fill: var(--bkn-slab-pink); }
.bkn-slab-feat:is(:hover, :focus-within) {
  & .bkn-slab-cover { rotate: 1deg; }
  & .bkn-slab-ink1 { translate: -3px 2px; }
  & .bkn-slab-ink2 { translate: 3px -2px; }
}

/* ---------- hero ---------- */
.bkn-slab-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}
.bkn-slab-h {
  display: grid;
  font: 900 clamp(40px, 8cqi + 8px, 112px)/.9 system-ui, -apple-system, "Segoe UI", sans-serif;
  letter-spacing: -.055em;
  text-transform: uppercase;
  & span { display: block; padding: .1em var(--bkn-slab-gut) .06em; border-bottom: var(--bkn-slab-rule); }
  & mark { background: var(--bkn-slab-pink); color: inherit; padding: 0 .06em; box-decoration-break: clone; -webkit-box-decoration-break: clone; }
}
.bkn-slab-h span.bkn-slab-ghost { background: var(--bkn-slab-ink); color: var(--bkn-slab-paper); }
.bkn-slab-side {
  display: grid;
  gap: 18px;
  align-content: start;
  padding: 20px var(--bkn-slab-gut) 28px;
  background-image: radial-gradient(var(--bkn-slab-ink) 1.1px, transparent 1.4px);
  background-size: 9px 9px;
  background-position: 0 0;
  & > p { max-width: 40ch; padding: 12px 14px; background: var(--bkn-slab-paper); border: 2px solid var(--bkn-slab-ink); font-size: 15px; font-weight: 550; text-wrap: pretty; }
}
.bkn-slab-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border: 2px solid var(--bkn-slab-ink);
  background: var(--bkn-slab-paper);
  & div { display: flex; flex-direction: column-reverse; justify-content: flex-end; gap: 4px; padding: 10px 12px; }
  & div + div { border-left: 2px solid var(--bkn-slab-ink); }
  & dt { font: 600 10.5px/1.3 var(--bkn-slab-mono); text-transform: uppercase; letter-spacing: .04em; }
  & dd { font-size: clamp(20px, 1.6cqi + 12px, 30px); font-weight: 900; letter-spacing: -.04em; line-height: 1; font-variant-numeric: tabular-nums; }
  & small { font: 600 10px/1 var(--bkn-slab-mono); letter-spacing: 0; }
}
.bkn-slab-sticker {
  position: absolute;
  top: clamp(8px, 2cqi, 20px);
  right: clamp(8px, 3cqi, 40px);
  display: grid;
  place-content: center;
  justify-items: center;
  width: clamp(96px, 12cqi, 140px);
  aspect-ratio: 1;
  border-radius: 50%;
  border: 2.5px solid var(--bkn-slab-ink);
  background: var(--bkn-slab-sun);
  box-shadow: 4px 4px 0 var(--bkn-slab-ink);
  rotate: 10deg;
  text-align: center;
  font: 600 clamp(10px, .7cqi + 6px, 12px)/1.25 var(--bkn-slab-mono);
  & b { font: 900 clamp(13px, 1cqi + 8px, 17px)/1 system-ui, sans-serif; text-transform: uppercase; letter-spacing: -.02em; margin-bottom: 3px; }
}

@container (min-width: 640px) {
  .bkn-slab-drop { grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); }
  .bkn-slab-list { border-right: 2px solid var(--bkn-slab-ink); }
  .bkn-slab-list li:last-child .bkn-slab-row { border-bottom: 0; }
  .bkn-slab-card { padding: 20px; }
}
@container (max-width: 639px) {
  .bkn-slab-drop .bkn-slab-row span { display: none; }
  .bkn-slab-list { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bkn-slab-list li:nth-child(odd) { border-right: 2px solid var(--bkn-slab-ink); }
  .bkn-slab-list li:last-child:nth-child(odd) { grid-column: 1 / -1; border-right: 0; }
  .bkn-slab-row { grid-template-columns: minmax(0, 1fr); grid-template-areas: "b" "em"; row-gap: 6px; padding: 10px 12px; }
  .bkn-slab-row em { justify-self: start; }
  .bkn-slab-list li:last-child:nth-child(odd) .bkn-slab-row { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "b em"; }
  .bkn-slab-feat { grid-template-columns: 84px minmax(0, 1fr); }
  .bkn-slab-big b { font-size: 44px; }
}
@container (min-width: 900px) {
  .bkn-slab-bar { grid-template-columns: 230px minmax(0, 1fr) auto; grid-template-areas: "logo nav bag"; }
  .bkn-slab-nav { border-top: 0; }
  .bkn-slab-menu {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    height: 100%;
    & li { border-right: var(--bkn-slab-rule); }
    & li:nth-child(-n + 2) { border-bottom: 0; }
  }
  .bkn-slab-top { height: 76px; }
  .bkn-slab-bag { padding: 0 28px; }
  .bkn-slab-hero { grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr); }
  .bkn-slab-h { border-right: var(--bkn-slab-rule); }
  .bkn-slab-h span:last-child { border-bottom: 0; }
  .bkn-slab-side { padding-top: clamp(110px, 14cqi, 170px); }
  .bkn-slab-stats { grid-template-columns: minmax(0, 1fr); }
  .bkn-slab-stats div + div { border-left: 0; border-top: 2px solid var(--bkn-slab-ink); }
}

@media (prefers-reduced-motion: reduce) {
  .bkn-slab .bkn-slab-drop, .bkn-slab .bkn-slab-drop.is-on { clip-path: none; transition: visibility 0s; }
  .bkn-slab :is(.bkn-slab-top, .bkn-slab-top::before, .bkn-slab-row::before, .bkn-slab-plus, .bkn-slab-ink1, .bkn-slab-ink2, .bkn-slab-cover, .bkn-slab-lb) { transition: none; }
  .bkn-slab .bkn-slab-feat:is(:hover, :focus-within) :is(.bkn-slab-ink1, .bkn-slab-ink2) { translate: none; }
}

