const bar = root.querySelector(".bkn-slab-bar");
const tops = [...root.querySelectorAll(".bkn-slab-top")];
const trigs = tops.filter((t) => t.hasAttribute("aria-expanded"));
const drops = trigs.map((t) => root.querySelector("#" + t.getAttribute("aria-controls")));
const bag = root.querySelector(".bkn-slab-bag");
const bagN = root.querySelector(".bkn-slab-n");
const addZ = root.querySelector(".bkn-slab-addz");
const reduce = matchMedia("(prefers-reduced-motion: reduce)");
let cur = -1, inBag = 3, added = 0;

// the open dropdown hangs from its own cell, clamped inside the component
function place(i) {
  const R = root.getBoundingClientRect();
  const c = trigs[i].getBoundingClientRect();
  const w = drops[i].offsetWidth;
  const gut = Math.max(16, Math.min(32, R.width * 0.03));
  const x = Math.max(gut, Math.min(R.width - w - gut - 10, c.left - R.left));
  root.style.setProperty("--bkn-slab-top", (bar.offsetTop + bar.offsetHeight - 2.5) + "px");
  root.style.setProperty("--bkn-slab-x", x + "px");
}
const items = (i) => [...drops[i].querySelectorAll("a[href], button")];
function open(i, focusFirst) {
  if (cur === i) { if (focusFirst) items(i)[0].focus(); return; }
  if (cur > -1) shut(false);
  cur = i;
  place(i);
  trigs[i].setAttribute("aria-expanded", "true");
  drops[i].inert = false;
  drops[i].classList.add("is-on");
  listen(true);
  if (focusFirst) items(i)[0].focus();
}
function shut(focusTrig) {
  if (cur < 0) return;
  const i = cur;
  cur = -1;
  trigs[i].setAttribute("aria-expanded", "false");
  drops[i].classList.remove("is-on");
  drops[i].inert = true;
  listen(false);
  if (focusTrig) trigs[i].focus();
}

trigs.forEach((t, i) => {
  t.addEventListener("click", () => (cur === i ? shut(false) : open(i)));
  t.addEventListener("keydown", (e) => {
    if (e.key === "ArrowDown") { e.preventDefault(); open(i, true); }
    else if (e.key === "Tab" && !e.shiftKey && cur === i) { e.preventDefault(); items(i)[0].focus(); }
  });
});
bar.addEventListener("keydown", (e) => {
  const k = tops.indexOf(document.activeElement);
  if (k < 0) return;
  if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
    e.preventDefault();
    const n = tops[(k + (e.key === "ArrowRight" ? 1 : -1) + tops.length) % tops.length];
    n.focus();
    if (cur > -1) { const ni = trigs.indexOf(n); if (ni > -1) open(ni); else shut(false); }
  } else if (e.key === "Escape" && cur > -1) { e.preventDefault(); shut(true); }
});
drops.forEach((d, i) => d.addEventListener("keydown", (e) => {
  const list = items(i);
  const k = list.indexOf(document.activeElement);
  if (e.key === "Escape") { e.preventDefault(); shut(true); return; }
  if (k < 0) return;
  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
    e.preventDefault();
    list[(k + (e.key === "ArrowDown" ? 1 : -1) + list.length) % list.length].focus();
  } else if (e.key === "Tab" && e.shiftKey && k === 0) {
    e.preventDefault(); trigs[i].focus();
  } else if (e.key === "Tab" && !e.shiftKey && k === list.length - 1) {
    e.preventDefault();
    const next = tops[tops.indexOf(trigs[i]) + 1] || bag;
    shut(false);
    next.focus();
  }
}));
root.addEventListener("focusout", (e) => {
  if (cur < 0) return;
  const to = e.relatedTarget;
  if (!to || !(bar.contains(to) || drops[cur].contains(to))) shut(false);
});
function onDoc(e) {
  if (!root.isConnected) { listen(false); return; }
  if (cur > -1 && !drops[cur].contains(e.target) && !trigs[cur].contains(e.target)) shut(false);
}
function listen(on) {
  if (on) document.addEventListener("pointerdown", onDoc, true);
  else document.removeEventListener("pointerdown", onDoc, true);
}

// add the featured zine; the bag counter rolls in three hard frames
addZ.addEventListener("click", () => {
  inBag += 1;
  added += 1;
  bagN.textContent = inBag;
  bag.setAttribute("aria-label", "Bag, " + inBag + " items");
  addZ.textContent = added === 1 ? "In your bag" : "In your bag × " + added;
  addZ.classList.add("is-done");
  if (!reduce.matches) bagN.animate([{ transform: "translateY(-110%)" }, { transform: "none" }], { duration: 240, easing: "steps(3, end)" });
});

root.addEventListener("click", (e) => {
  const a = e.target.closest('a[href^="#"]');
  if (!a) return;
  e.preventDefault();
  if (cur > -1 && drops[cur].contains(a)) shut(true);
});
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); listen(false); return; }
  if (cur > -1) place(cur);
});
ro.observe(root);

