@property --bkn-island-cw { syntax: "<color>"; inherits: true; initial-value: oklch(0.8 0.055 70); }

.bkn-island {
  --bkn-island-stone: oklch(0.945 0.012 75);
  --bkn-island-ink: oklch(0.19 0.01 60);
  --bkn-island-glow: oklch(0.82 0.11 75);
  --bkn-island-on: oklch(0.96 0.008 80);
  --bkn-island-dim: color-mix(in oklch, var(--bkn-island-on) 58%, var(--bkn-island-ink));
  --bkn-island-hair: color-mix(in oklch, var(--bkn-island-on) 12%, transparent);
  --bkn-island-muted: color-mix(in oklch, var(--bkn-island-ink) 60%, var(--bkn-island-stone));
  --bkn-island-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  --bkn-island-gut: clamp(16px, 4cqi, 48px);
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  width: 100%;
  min-height: 600px;
  background:
    radial-gradient(60% 70% at 75% 60%, color-mix(in oklch, var(--bkn-island-cw) 30%, transparent), transparent 70%),
    var(--bkn-island-stone);
  color: var(--bkn-island-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  transition: --bkn-island-cw .7s cubic-bezier(.3, .7, .2, 1);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, p, ul, li, fieldset, legend) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(a, button, input):focus-visible { outline: 2px solid var(--bkn-island-glow); outline-offset: 2px; border-radius: 10px; }
}
.bkn-island[data-cw="Graphite"] { --bkn-island-cw: oklch(0.36 0.012 260); }
.bkn-island[data-cw="Moss"] { --bkn-island-cw: oklch(0.56 0.06 135); }

/* ---------- the stage: one capsule, many panes ---------- */
.bkn-island-stage {
  position: absolute;
  top: 14px;
  left: 50%;
  z-index: 5;
  width: min(720px, 100cqi - 24px);
  height: 460px;
  translate: -50% 0;
  pointer-events: none;
  color: var(--bkn-island-on);
}
.bkn-island-shape {
  position: absolute;
  inset: 0;
  filter: drop-shadow(0 12px 22px oklch(0.2 0.02 60 / .28)) drop-shadow(0 2px 3px oklch(0.2 0.02 60 / .18));
}
.bkn-island-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(color-mix(in oklch, var(--bkn-island-ink) 88%, white), var(--bkn-island-ink) 60px);
  clip-path: inset(0px 40% 408px 40% round 26px);
}
.bkn-island-pane {
  position: absolute;
  top: 0;
  left: 50%;
  translate: -50% 0;
  max-width: 100%;
  transform-origin: 50% 0;
  visibility: hidden;
  opacity: 0;
  transition: visibility 0s .2s, opacity 0s .2s;
  &.is-on { visibility: visible; opacity: 1; pointer-events: auto; transition: none; }
}

.bkn-island-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 52px;
  padding: 0 6px 0 16px;
  white-space: nowrap;
}
.bkn-island-logo {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-right: 10px;
  & svg { width: 22px; height: 22px; fill: none; stroke: var(--bkn-island-glow); stroke-width: 2; stroke-linecap: round; }
  & span { font-size: 17px; font-weight: 700; letter-spacing: -.04em; }
}
.bkn-island-links { display: none; gap: 2px; margin-right: 6px; }
.bkn-island-link {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 12px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 520;
  color: var(--bkn-island-dim);
  transition: color .15s, background-color .15s;
  &:hover { color: var(--bkn-island-on); background: var(--bkn-island-hair); }
}
.bkn-island-ic {
  position: relative;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  color: var(--bkn-island-dim);
  transition: color .15s, background-color .15s, scale .3s var(--bkn-island-spring);
  &:hover { color: var(--bkn-island-on); background: var(--bkn-island-hair); }
  &:active { scale: .92; }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
}
.bkn-island-count {
  position: absolute;
  top: 4px;
  right: 3px;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  border-radius: 9px;
  background: var(--bkn-island-glow);
  color: var(--bkn-island-ink);
  font-size: 10.5px;
  font-weight: 750;
  line-height: 17px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

.bkn-island-search { width: min(520px, 100%); padding: 6px 6px 8px; }
.bkn-island-field {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  height: 40px;
  padding: 0 4px 0 12px;
  & svg { width: 19px; height: 19px; fill: none; stroke: var(--bkn-island-glow); stroke-width: 1.8; stroke-linecap: round; }
  & input { min-width: 0; height: 100%; border: 0; background: none; color: var(--bkn-island-on); font: inherit; font-size: 15.5px; caret-color: var(--bkn-island-glow); }
  & input::placeholder { color: var(--bkn-island-dim); }
  & input:focus { outline: none; }
}
.bkn-island-esc { height: 26px; padding: 0 8px; border-radius: 7px; border: 1px solid var(--bkn-island-hair); font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--bkn-island-dim); &:hover { color: var(--bkn-island-on); } }
.bkn-island-sugg {
  display: grid;
  gap: 2px;
  margin-top: 4px;
  padding-top: 6px;
  border-top: 1px solid var(--bkn-island-hair);
  &:empty { display: none; }
  & li { display: grid; grid-template-columns: 32px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 7px 10px; border-radius: 12px; cursor: pointer; }
  & li[aria-selected="true"] { background: var(--bkn-island-hair); }
  & i { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; background: var(--bkn-island-hair); color: var(--bkn-island-glow); font: 700 12px/1 system-ui; font-style: normal; }
  & b { font-size: 14px; font-weight: 600; }
  & mark { background: none; color: var(--bkn-island-glow); }
  & small { display: block; font-size: 12px; color: var(--bkn-island-dim); }
  & em { font-style: normal; font-size: 11.5px; color: var(--bkn-island-dim); opacity: 0; }
  & li[aria-selected="true"] em { opacity: 1; }
}

.bkn-island-bag { width: min(380px, 100%); padding: 16px 16px 14px; display: grid; gap: 10px; }
.bkn-island-ph { display: flex; justify-content: space-between; align-items: baseline; & b { font-size: 16px; font-weight: 650; } & span { font-size: 12.5px; color: var(--bkn-island-dim); font-variant-numeric: tabular-nums; } }
.bkn-island-lines { display: grid; }
.bkn-island-line {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  grid-template-areas: "th name price" "th var step";
  align-items: center;
  column-gap: 12px;
  padding: 10px 0;
  border-top: 1px solid var(--bkn-island-hair);
  & .bkn-island-th { position: relative; grid-area: th; display: grid; place-items: center; width: 44px; height: 44px; border-radius: 12px; background: var(--bkn-island-hair); }
  & .bkn-island-th svg { width: 30px; height: 30px; fill: none; stroke: var(--bkn-island-glow); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  &[style*="--c"] .bkn-island-th::after { content: ""; position: absolute; right: -3px; bottom: -3px; width: 13px; height: 13px; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 2.5px var(--bkn-island-ink); }
  & b { grid-area: name; font-size: 14px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { grid-area: var; font-size: 12px; color: var(--bkn-island-dim); }
  & .bkn-island-price { grid-area: price; justify-self: end; font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; }
}
.bkn-island-step {
  grid-area: step;
  justify-self: end;
  display: flex;
  align-items: center;
  border: 1px solid var(--bkn-island-hair);
  border-radius: 999px;
  & button { width: 26px; height: 24px; display: grid; place-items: center; color: var(--bkn-island-dim); border-radius: 999px; font-size: 15px; line-height: 1; }
  & button:hover { color: var(--bkn-island-on); background: var(--bkn-island-hair); }
  & output { min-width: 18px; text-align: center; font-size: 12.5px; font-weight: 600; font-variant-numeric: tabular-nums; }
}
.bkn-island-ship { font-size: 12.5px; color: var(--bkn-island-dim); & b { color: var(--bkn-island-glow); font-weight: 600; } }
.bkn-island-sub { display: flex; justify-content: space-between; align-items: baseline; padding-top: 8px; border-top: 1px solid var(--bkn-island-hair); & span { font-size: 13px; color: var(--bkn-island-dim); } & b { font-size: 20px; font-weight: 650; letter-spacing: -.02em; font-variant-numeric: tabular-nums; } }
.bkn-island-checkout {
  display: grid;
  place-items: center;
  height: 42px;
  border-radius: 999px;
  background: var(--bkn-island-on);
  color: var(--bkn-island-ink);
  font-size: 14.5px;
  font-weight: 650;
  transition: background-color .15s, scale .3s var(--bkn-island-spring);
  &:hover { background: var(--bkn-island-glow); }
  &:active { scale: .98; }
  &[aria-disabled="true"] { opacity: .4; pointer-events: none; }
}
.bkn-island-empty { padding: 14px 0 4px; font-size: 13.5px; color: var(--bkn-island-dim); }

.bkn-island-shop { width: min(640px, 100%); padding: 10px; display: grid; gap: 6px; }
.bkn-island-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  & a { display: grid; justify-items: start; gap: 2px; padding: 12px; border-radius: 16px; background: var(--bkn-island-hair); transition: background-color .15s, translate .35s var(--bkn-island-spring); }
  & a:hover, & a:focus-visible { background: color-mix(in oklch, var(--bkn-island-on) 18%, transparent); translate: 0 -2px; }
  & svg { width: 40px; height: 40px; margin-bottom: 6px; fill: none; stroke: var(--bkn-island-glow); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & b { font-size: 15px; font-weight: 650; }
  & small { font-size: 12.5px; color: var(--bkn-island-dim); font-variant-numeric: tabular-nums; }
}
.bkn-island-all {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 10px 4px;
  font-size: 13.5px;
  font-weight: 560;
  color: var(--bkn-island-dim);
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; transition: translate .3s var(--bkn-island-spring); }
  &:hover { color: var(--bkn-island-on); }
  &:hover svg { translate: 3px 0; }
}
.bkn-island-x {
  position: absolute;
  top: 10px;
  right: 10px;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  color: var(--bkn-island-dim);
  &:hover { color: var(--bkn-island-on); background: var(--bkn-island-hair); }
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
}
.bkn-island-menu {
  width: min(320px, 100%);
  padding: 8px;
  display: grid;
  & a { display: grid; padding: 10px 12px; border-radius: 14px; font-size: 18px; font-weight: 650; letter-spacing: -.02em; }
  & a:hover, & a:focus-visible { background: var(--bkn-island-hair); }
  & small { font-size: 12.5px; font-weight: 450; letter-spacing: 0; color: var(--bkn-island-dim); }
}
.bkn-island-note {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 40px;
  padding: 0 18px 0 12px;
  white-space: nowrap;
  font-size: 13.5px;
  font-weight: 560;
}
.bkn-island-swatch { width: 18px; height: 18px; border-radius: 50%; background: var(--c, var(--bkn-island-glow)); box-shadow: 0 0 0 3px var(--bkn-island-hair); }
.bkn-island-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------- hero ---------- */
.bkn-island-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 92px var(--bkn-island-gut) clamp(28px, 4cqi, 48px);
}
.bkn-island-copy { display: grid; justify-items: start; gap: 14px; }
.bkn-island-kick { display: flex; gap: 10px; align-items: baseline; font-size: 13px; font-weight: 650; & span { font-weight: 450; color: var(--bkn-island-muted); } }
.bkn-island-h { max-width: 11ch; font-size: clamp(40px, 5.6cqi + 14px, 80px); line-height: .96; font-weight: 640; letter-spacing: -.05em; text-wrap: balance; }
.bkn-island-lede { max-width: 42ch; color: var(--bkn-island-muted); font-size: clamp(15px, .4cqi + 13.5px, 17px); text-wrap: pretty; }
.bkn-island-cw {
