.bkn-island-cush { fill: color-mix(in oklch, var(--bkn-island-cw) 55%, black); }
.bkn-island-glint { fill: none; stroke: oklch(1 0 0 / .45); stroke-width: 4; stroke-linecap: round; }

@container (min-width: 640px) {
  .bkn-island-links { display: flex; }
