const reduce = matchMedia("(prefers-reduced-motion: reduce)");
const SPRING = getComputedStyle(root).getPropertyValue("--bkn-island-spring").trim() || "cubic-bezier(.2,.9,.25,1)";
const stage = root.querySelector(".bkn-island-stage");
const bg = root.querySelector(".bkn-island-bg");
const panes = {};
root.querySelectorAll(".bkn-island-pane").forEach((p) => { panes[p.dataset.pane] = p; });
const goBtns = [...root.querySelectorAll(".bkn-island-bar .bkn-island-go")];
const countEl = root.querySelector(".bkn-island-count");
const bagBtn = root.querySelector(".bkn-island-bagbtn");
const sr = root.querySelector(".bkn-island-sr");
const q = root.querySelector(".bkn-island-q");
const sugg = root.querySelector(".bkn-island-sugg");
const linesEl = root.querySelector(".bkn-island-lines");
const shipEl = root.querySelector(".bkn-island-ship");
const totalEl = root.querySelector(".bkn-island-total");
const bagN = root.querySelector(".bkn-island-bagn");
const checkout = root.querySelector(".bkn-island-checkout");
const noteT = root.querySelector(".bkn-island-notet");
const noteSw = root.querySelector(".bkn-island-swatch");
const addBtn = root.querySelector(".bkn-island-add");
const cwName = root.querySelector(".bkn-island-cwname");

const COLORS = { Sandstone: "oklch(0.8 0.055 70)", Graphite: "oklch(0.36 0.012 260)", Moss: "oklch(0.56 0.06 135)" };
const GLYPH = {
  arc: '<path d="M10 30v-6a14 14 0 0 1 28 0v6"/><rect x="7" y="27" width="8" height="13" rx="4"/><rect x="33" y="27" width="8" height="13" rx="4"/>',
  pebble: '<circle cx="17" cy="22" r="7"/><path d="M17 29v10"/><circle cx="32" cy="22" r="7"/><path d="M32 29v10"/>',
  dune: '<rect x="9" y="14" width="30" height="24" rx="12"/><circle cx="24" cy="26" r="5"/>',
  cable: '<path d="M12 12v8a6 6 0 0 0 12 0v-4a6 6 0 0 1 12 0v20"/><path d="M9 12h6M33 36h6"/>',
  cushion: '<circle cx="24" cy="24" r="13"/><circle cx="24" cy="24" r="6"/>'
};
const PRODUCTS = {
  arc: { n: "Orrin Arc", p: 349 }, pebble: { n: "Orrin Pebble", p: 179 }, dune: { n: "Dune speaker", p: 249 },
  cable: { n: "Braided cable 1.2 m", p: 29 }, cushion: { n: "Ear cushions, pair", p: 39 }
};
const INDEX = [
  { t: "Orrin Arc", s: "Over-ear · $349", k: "arc" },
  { t: "Orrin Pebble", s: "In-ear · $179", k: "pebble" },
  { t: "Dune speaker", s: "Portable · $249", k: "dune" },
  { t: "Braided cable 1.2 m", s: "Accessory · $29", k: "cable" },
  { t: "Ear cushions, pair", s: "Accessory · $39", k: "cushion" },
  { t: "Pairing two devices", s: "Support article" },
  { t: "Firmware 2.3 release notes", s: "Support article" },
  { t: "Battery care", s: "Support article" }
];
let bag = [{ k: "arc", v: "Sandstone", q: 1 }, { k: "cable", v: "Graphite", q: 1 }];
let state = "bar", opener = null, noteTimer = 0, act = 0, hits = [];

// radio groups are document-global by name; give this instance its own
const uid = "bkn-island-cw-" + Math.random().toString(36).slice(2, 8);
root.querySelectorAll('input[name="bkn-island-cw"]').forEach((r) => { r.name = uid; });

// ---------- the morph ----------
function clipFor(st) {
  const p = panes[st];
  const W = stage.clientWidth, H = stage.clientHeight;
  const w = Math.min(p.offsetWidth, W), h = p.offsetHeight;
  const x = Math.max(0, (W - w) / 2);
  const r = st === "bar" || st === "note" ? h / 2 : 26;
  return "inset(0px " + x.toFixed(1) + "px " + Math.max(0, H - h).toFixed(1) + "px " + x.toFixed(1) + "px round " + r.toFixed(1) + "px)";
}
function reclip(animate) {
  const next = clipFor(state);
  const from = getComputedStyle(bg).clipPath;   // mid-flight value if a morph is running
  bg.getAnimations().forEach((a) => a.cancel());
  bg.style.clipPath = next;
  if (animate && !reduce.matches && from && from !== "none" && from !== next) {
    bg.animate([{ clipPath: from }, { clipPath: next }], { duration: 680, easing: SPRING });
  }
}
function morph(to, by) {
  if (to === state) return;
  const from = state;
  state = to;
  clearTimeout(noteTimer);
  const a = panes[from], b = panes[to];
  const hadFocus = a.contains(document.activeElement) || document.activeElement === document.body;
  a.classList.remove("is-on");
  a.inert = true;
  b.classList.add("is-on");
  b.inert = false;
  root.dataset.state = to;
  goBtns.forEach((g) => g.setAttribute("aria-expanded", String(g.dataset.go === to)));
  if (!reduce.matches) {
    a.animate([{ opacity: 1, filter: "blur(0px)", transform: "scale(1)" }, { opacity: 0, filter: "blur(6px)", transform: "scale(.96)" }],
      { duration: 180, easing: "cubic-bezier(.4,0,1,1)" });
    b.animate([{ opacity: 0, filter: "blur(6px)", transform: "scale(.94)" }, { opacity: 1, filter: "blur(0px)", transform: "scale(1)" }],
      { duration: 440, delay: 80, easing: "cubic-bezier(.2,.9,.25,1)", fill: "backwards" });
  }
  reclip(true);
  listen(to !== "bar");
  if (to === "bar") {
    // hand focus back to whatever opened the pane, or the menu button when that one is hidden
    const o = opener && opener.offsetParent ? opener : goBtns.find((g) => g.dataset.go === "menu" && g.offsetParent);
    if (hadFocus && o) o.focus({ preventScroll: true });
    return;
  }
  if (by) opener = by;
  if (to === "search") { q.value = ""; renderSugg(); q.focus({ preventScroll: true }); }
  else if (to !== "note") { const f = b.querySelector("a[href], button, input"); if (f) f.focus({ preventScroll: true }); }
}
function note(text, color, then) {
  noteT.textContent = text;
  noteSw.style.setProperty("--c", color || "var(--bkn-island-glow)");
  sr.textContent = text;
  morph("note");
  noteTimer = setTimeout(() => { if (root.isConnected && state === "note") { morph("bar"); if (then) then(); } }, 1900);
}

// ---------- bag ----------
const money = (v) => "$" + v.toLocaleString("en-US");
const qty = () => bag.reduce((s, l) => s + l.q, 0);
function renderBag() {
  linesEl.textContent = "";
  bag.forEach((l, i) => {
    const pr = PRODUCTS[l.k];
    const li = document.createElement("li");
    li.className = "bkn-island-line";
    if (COLORS[l.v]) li.style.setProperty("--c", COLORS[l.v]);
    li.innerHTML = '<span class="bkn-island-th"><svg viewBox="0 0 48 48" aria-hidden="true">' + GLYPH[l.k] + '</svg></span><b></b><small></small><span class="bkn-island-price"></span><span class="bkn-island-step"><button type="button" data-d="-1"></button><output></output><button type="button" data-d="1">+</button></span>';
    li.querySelector("b").textContent = pr.n;
    li.querySelector("small").textContent = l.v;
    li.querySelector(".bkn-island-price").textContent = money(pr.p * l.q);
    li.querySelector("output").textContent = l.q;
    const minus = li.querySelector('[data-d="-1"]');
    minus.textContent = l.q === 1 ? "×" : "−";
    minus.setAttribute("aria-label", l.q === 1 ? "Remove " + pr.n : "One fewer " + pr.n);
    li.querySelector('[data-d="1"]').setAttribute("aria-label", "One more " + pr.n);
    li.querySelectorAll("button").forEach((b) => b.addEventListener("click", () => {
      l.q += +b.dataset.d;
      if (l.q <= 0) bag.splice(i, 1);
      renderBag();
      const keep = linesEl.querySelectorAll(".bkn-island-step button")[Math.min(i * 2 + (+b.dataset.d > 0 ? 1 : 0), linesEl.querySelectorAll(".bkn-island-step button").length - 1)];
      (keep || checkout).focus({ preventScroll: true });
    }));
    linesEl.append(li);
  });
  if (!bag.length) {
    const li = document.createElement("li");
    li.className = "bkn-island-empty";
    li.textContent = "Your bag is empty. The Arc is a good place to start.";
    linesEl.append(li);
  }
  const total = bag.reduce((s, l) => s + PRODUCTS[l.k].p * l.q, 0);
  const n = qty();
  totalEl.textContent = money(total);
  bagN.textContent = n + (n === 1 ? " item" : " items");
  shipEl.innerHTML = total >= 150 ? "<b>Free express shipping</b> on this order" : total ? "Add <b>" + money(150 - total) + "</b> for free express shipping" : "Free express shipping over $150";
  checkout.setAttribute("aria-disabled", String(!n));
  countEl.textContent = n;
  countEl.hidden = !n;
  bagBtn.setAttribute("aria-label", "Bag, " + n + (n === 1 ? " item" : " items"));
}
function addToBag(k, v) {
  const line = bag.find((l) => l.k === k && l.v === v);
  if (line) line.q += 1; else bag.push({ k, v, q: 1 });
  renderBag();
  note("Added " + PRODUCTS[k].n + (v !== "—" ? " · " + v : ""), COLORS[v], () => {
    if (!reduce.matches) countEl.animate([{ transform: "scale(1)" }, { transform: "scale(1.5)" }, { transform: "scale(1)" }], { duration: 520, easing: SPRING });
  });
}

// ---------- search ----------
function renderSugg() {
  const s = q.value.trim().toLowerCase();
  hits = (s ? INDEX.filter((e) => e.t.toLowerCase().includes(s) || e.s.toLowerCase().includes(s)) : INDEX.slice(0, 4)).slice(0, 5);
  sugg.textContent = "";
  hits.forEach((e, i) => {
    const li = document.createElement("li");
    li.id = "bkn-island-o" + i;
    li.setAttribute("role", "option");
    const ic = document.createElement("i");
    ic.textContent = e.k ? e.t.replace("Orrin ", "").slice(0, 2) : "?";
    const tx = document.createElement("span");
    const b = document.createElement("b");
    const at = s ? e.t.toLowerCase().indexOf(s) : -1;
    if (at > -1) { const m = document.createElement("mark"); m.textContent = e.t.slice(at, at + s.length); b.append(e.t.slice(0, at), m, e.t.slice(at + s.length)); }
    else b.textContent = e.t;
    const sm = document.createElement("small");
    sm.textContent = e.s;
    tx.append(b, sm);
    const em = document.createElement("em");
    em.textContent = e.k ? "Add ↵" : "Open ↵";
    li.append(ic, tx, em);
    li.addEventListener("pointerdown", (ev) => ev.preventDefault());
    li.addEventListener("pointermove", () => mark(i));
    li.addEventListener("click", () => pick(i));
    sugg.append(li);
  });
  if (!hits.length) {
    const li = document.createElement("li");
    li.textContent = "No match. Try “arc” or “battery”.";
    li.style.cursor = "default";
    sugg.append(li);
  }
  mark(hits.length ? 0 : -1);
}
function mark(i) {
  act = i;
  [...sugg.children].forEach((li, k) => li.setAttribute("aria-selected", String(k === i)));
  if (i > -1) q.setAttribute("aria-activedescendant", "bkn-island-o" + i); else q.removeAttribute("aria-activedescendant");
}
function pick(i) {
  const e = hits[i];
  if (!e) return;
  if (e.k) addToBag(e.k, e.k === "arc" || e.k === "pebble" ? cw() : "—");
  else note("Opening “" + e.t + "”");
}
q.addEventListener("input", renderSugg);
q.addEventListener("keydown", (e) => {
  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
    e.preventDefault();
    if (hits.length) mark((act + (e.key === "ArrowDown" ? 1 : -1) + hits.length) % hits.length);
  } else if (e.key === "Enter" && act > -1) { e.preventDefault(); pick(act); }
});

// ---------- wiring ----------
root.querySelectorAll("[data-go]").forEach((b) => b.addEventListener("click", (e) => {
  e.preventDefault();
  const to = b.dataset.go;
  if (state === to) morph("bar");
  else morph(to, goBtns.find((g) => g.dataset.go === to) || opener);
}));
root.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && state !== "bar") { e.preventDefault(); morph("bar"); }
});
function onDoc(e) {
  if (!root.isConnected) { listen(false); return; }
  if (state !== "bar" && state !== "note" && !panes[state].contains(e.target) && !e.target.closest(".bkn-island-bar")) morph("bar");
}
let listening = false;
function listen(on) {
  if (on === listening) return;
  listening = on;
  if (on) document.addEventListener("pointerdown", onDoc, true);
  else document.removeEventListener("pointerdown", onDoc, true);
}
root.addEventListener("click", (e) => {
  const a = e.target.closest('a[href^="#"]');
  if (!a || a.dataset.go) return;
  e.preventDefault();
  if (state !== "bar" && panes[state].contains(a)) {
    const label = (a.querySelector("b") || a).childNodes[0].textContent.trim();
    note(a.classList.contains("bkn-island-checkout") ? "Taking you to checkout" : "Opening " + label);
  }
});

const cw = () => root.querySelector('input[name="' + uid + '"]:checked').value;
root.querySelectorAll('input[name="' + uid + '"]').forEach((r) => r.addEventListener("change", () => {
  root.dataset.cw = r.value;
  cwName.textContent = r.value;
}));
addBtn.addEventListener("click", () => addToBag("arc", cw()));

// The capsule follows its content: any size change of the open pane re-morphs it.
const ro = new ResizeObserver((entries) => {
  if (!root.isConnected) { ro.disconnect(); listen(false); return; }
  if (entries.some((en) => en.target === panes[state] || en.target === stage)) reclip(true);
});
Object.values(panes).forEach((p) => ro.observe(p));
ro.observe(stage);
renderBag();
reclip(false);

