@property --bkn-press-hue { syntax: "<number>"; inherits: true; initial-value: 25; }
@property --bkn-press-fl { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --bkn-press-fr { syntax: "<length>"; inherits: false; initial-value: 0px; }

.bkn-press {
  --bkn-press-paper: oklch(0.968 0.012 88);
  --bkn-press-ink: oklch(0.2 0.012 70);
  --bkn-press-chroma: 0.13;
  --bkn-press-sect: oklch(0.5 var(--bkn-press-chroma) var(--bkn-press-hue));
  --bkn-press-deep: oklch(0.31 calc(var(--bkn-press-chroma) * .7) var(--bkn-press-hue));
  --bkn-press-muted: color-mix(in oklch, var(--bkn-press-ink) 62%, var(--bkn-press-paper));
  --bkn-press-rule: color-mix(in oklch, var(--bkn-press-ink) 16%, transparent);
  --bkn-press-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --bkn-press-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  --bkn-press-gut: clamp(16px, 4cqi, 48px);
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  overflow: clip;
  width: 100%;
  min-height: 560px;
  background: var(--bkn-press-paper);
  color: var(--bkn-press-ink);
  font: 400 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  transition: --bkn-press-hue .65s cubic-bezier(.3, .7, .2, 1);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, p, ol, li, figure) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(a) { color: inherit; text-decoration: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(a, button, [tabindex="0"]):focus-visible { outline: 2px solid var(--bkn-press-sect); outline-offset: 2px; border-radius: 4px; }
}

/* ---------- masthead ---------- */
.bkn-press-mast {
  display: grid;
  justify-items: center;
  gap: 6px;
  padding: 10px var(--bkn-press-gut) 14px;
}
.bkn-press-top {
  justify-self: stretch;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--bkn-press-rule);
  font-size: 12.5px;
}
.bkn-press-date {
  display: flex;
  flex-wrap: wrap;
  gap: 0 10px;
  & time { font-weight: 650; }
  & span { color: var(--bkn-press-muted); font-variant-numeric: tabular-nums; }
}
.bkn-press-wx {
  display: none;
  align-items: center;
  gap: 6px;
  color: var(--bkn-press-muted);
  & svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
}
.bkn-press-acts {
  display: flex;
  align-items: center;
  gap: 14px;
  & .bkn-press-signin { display: none; font-weight: 560; }
  & .bkn-press-signin:hover { text-decoration: underline; text-underline-offset: 3px; }
}
.bkn-press-subs {
  padding: 6px 12px;
  border-radius: 3px;
  background: var(--bkn-press-ink);
  color: var(--bkn-press-paper);
  font-weight: 650;
  transition: background-color .3s;
  & span { display: none; font-weight: 450; opacity: .8; }
  &:hover { background: var(--bkn-press-deep); }
}
.bkn-press-title {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, 1.4cqi, 16px);
  margin-top: 6px;
  & svg { width: clamp(26px, 4.6cqi, 58px); height: auto; fill: none; stroke: var(--bkn-press-ink); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  & .bkn-press-hb { fill: var(--bkn-press-ink); stroke: none; }
  & span { font: 800 clamp(22px, 6cqi + 1px, 72px)/1 var(--bkn-press-serif); letter-spacing: -.025em; white-space: nowrap; }
}
.bkn-press-motto {
  display: flex;
  align-items: center;
  gap: 10px;
  font: italic 400 clamp(12px, .5cqi + 10px, 14px)/1.3 var(--bkn-press-serif);
  color: var(--bkn-press-muted);
  & i { width: 4px; height: 4px; rotate: 45deg; background: var(--bkn-press-sect); }
}

/* ---------- the rail ---------- */
.bkn-press-nav {
  position: relative;
  border-top: 3px double var(--bkn-press-ink);
  border-bottom: 1px solid var(--bkn-press-ink);
}
.bkn-press-rail {
  position: relative;
  display: flex;
  gap: 2px;
  padding: 6px var(--bkn-press-gut);
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-snap-type: x proximity;
  scroll-padding-inline: 48px;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 var(--bkn-press-fl), #000 calc(100% - var(--bkn-press-fr)), transparent);
  mask-image: linear-gradient(90deg, transparent, #000 var(--bkn-press-fl), #000 calc(100% - var(--bkn-press-fr)), transparent);
  &::-webkit-scrollbar { display: none; }
}
@keyframes bkn-press-edges {
  0% { --bkn-press-fl: 0px; --bkn-press-fr: 56px; }
  6% { --bkn-press-fl: 56px; }
  94% { --bkn-press-fr: 56px; }
  100% { --bkn-press-fl: 56px; --bkn-press-fr: 0px; }
}
@supports (animation-timeline: scroll()) {
  .bkn-press-rail { animation: bkn-press-edges linear both; animation-timeline: scroll(self inline); }
}
.bkn-press-band {
  position: absolute;
  top: 6px;
  left: 0;
  height: 34px;
  width: var(--bkn-press-sw, 100%);
  border-radius: 999px;
  background: var(--bkn-press-deep);
  clip-path: inset(0 100% 0 0 round 999px);
  pointer-events: none;
}
.bkn-press-tab {
  position: relative;
  flex: none;
  height: 34px;
  padding: 0 14px;
  border-radius: 999px;
  scroll-snap-align: center;
  font-size: 12.5px;
  font-weight: 650;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: color-mix(in oklch, var(--bkn-press-ink) 74%, var(--bkn-press-paper));
  transition: color .2s;
  &:hover { color: var(--bkn-press-ink); }
  &[aria-selected="true"] { color: var(--bkn-press-paper); transition: color .2s .08s; }
  &:focus-visible { outline-offset: -2px; border-radius: 999px; }
}
.bkn-press-arw {
  position: absolute;
  top: 50%;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  translate: 0 -50%;
  border-radius: 50%;
  background: var(--bkn-press-paper);
  box-shadow: 0 0 0 1px var(--bkn-press-rule), 0 4px 10px -4px oklch(0.2 0.01 70 / .35);
  transition: opacity .2s, scale .25s;
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &[data-d="-1"] { left: 8px; }
  &[data-d="1"] { right: 8px; }
  &:hover { scale: 1.08; }
}
.bkn-press-nav:not(.can-l) .bkn-press-arw[data-d="-1"], .bkn-press-nav:not(.can-r) .bkn-press-arw[data-d="1"] { opacity: 0; scale: .7; pointer-events: none; }

/* ---------- the section front ---------- */
.bkn-press-front {
