  align-items: baseline;
  gap: 10px;
  font-size: 12px;
  & b { font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--bkn-press-sect); }
  & span { color: var(--bkn-press-muted); }
}
.bkn-press-hl {
  font: 700 clamp(24px, 2.6cqi + 12px, 40px)/1.08 var(--bkn-press-serif);
  letter-spacing: -.015em;
