  & a { background: linear-gradient(var(--bkn-press-sect), var(--bkn-press-sect)) 0 100% / 0 2px no-repeat; transition: background-size .5s cubic-bezier(.2, .9, .25, 1); }
  & a:hover { background-size: 100% 2px; }
}
.bkn-press-std { max-width: 52ch; font: 400 clamp(15.5px, .5cqi + 13px, 17.5px)/1.5 var(--bkn-press-serif); color: color-mix(in oklch, var(--bkn-press-ink) 80%, var(--bkn-press-paper)); text-wrap: pretty; }
.bkn-press-by { font-size: 12.5px; font-weight: 600; color: var(--bkn-press-muted); }
.bkn-press-fig {
  display: none;
  align-content: start;
  gap: 6px;
  & svg { width: 100%; height: auto; aspect-ratio: 16 / 11; border-radius: 2px; }
  & figcaption { font: italic 12px/1.3 var(--bkn-press-serif); color: var(--bkn-press-muted); }
}
.bkn-press-sky { fill: oklch(0.9 0.04 var(--bkn-press-hue)); }
.bkn-press-sun { fill: oklch(0.72 0.13 var(--bkn-press-hue)); translate: var(--bkn-press-sx, 0px) 0; transition: translate .9s var(--bkn-press-spring); }
.bkn-press-far { fill: oklch(0.62 0.07 var(--bkn-press-hue)); }
.bkn-press-water { fill: oklch(0.4 0.07 var(--bkn-press-hue)); }
.bkn-press-ripple { fill: none; stroke: oklch(0.82 0.05 var(--bkn-press-hue)); stroke-width: 2; stroke-linecap: round; }
.bkn-press-reeds { fill: none; stroke: oklch(0.25 0.04 var(--bkn-press-hue)); stroke-width: 2.4; stroke-linecap: round; }
.bkn-press-side { display: grid; gap: 4px; align-content: start; }
.bkn-press-moreh { padding-bottom: 6px; border-bottom: 2px solid var(--bkn-press-ink); font-size: 12px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; & span { color: var(--bkn-press-sect); } }
.bkn-press-more {
  counter-reset: bkn-press-n;
  & li { counter-increment: bkn-press-n; border-bottom: 1px solid var(--bkn-press-rule); }
  & a { display: grid; grid-template-columns: 26px minmax(0, 1fr); gap: 8px; padding: 10px 0; font: 600 15px/1.3 var(--bkn-press-serif); text-wrap: pretty; }
  & a::before { content: counter(bkn-press-n); font: 700 22px/1 var(--bkn-press-serif); color: var(--bkn-press-sect); font-variant-numeric: lining-nums; }
  & a:hover { color: var(--bkn-press-deep); text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; }
}

@container (min-width: 600px) {
  .bkn-press-wx { display: inline-flex; }
  .bkn-press-top { grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); }
  .bkn-press-acts { justify-self: end; }
  .bkn-press-acts .bkn-press-signin { display: inline; }
  .bkn-press-front { grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); column-gap: 28px; }
  .bkn-press-side { grid-column: 1 / -1; }
  .bkn-press-fig { display: grid; }
}
@container (min-width: 960px) {
  .bkn-press-subs span { display: inline; }
  .bkn-press-front { grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr) minmax(0, .95fr); column-gap: 0; }
  .bkn-press-front > * { padding-inline: 24px; }
  .bkn-press-front > * + * { border-left: 1px solid var(--bkn-press-rule); }
  .bkn-press-lead { padding-left: 0; }
  .bkn-press-side { grid-column: auto; padding-right: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .bkn-press { transition: none; }
  .bkn-press .bkn-press-sun, .bkn-press .bkn-press-hl a, .bkn-press .bkn-press-arw { transition: none; }
}

