const reduce = matchMedia("(prefers-reduced-motion: reduce)");
const SPRING = getComputedStyle(root).getPropertyValue("--bkn-press-spring").trim() || "cubic-bezier(.2,.9,.25,1)";
const nav = root.querySelector(".bkn-press-nav");
const rail = root.querySelector(".bkn-press-rail");
const band = root.querySelector(".bkn-press-band");
const tabs = [...root.querySelectorAll(".bkn-press-tab")];
const panel = root.querySelector(".bkn-press-front");
const $ = (s) => root.querySelector(s);
const parts = {
  sec: $(".bkn-press-sec"), upd: $(".bkn-press-upd"), hl: $(".bkn-press-hl a"), std: $(".bkn-press-std"),
  by: $(".bkn-press-by"), figsec: $(".bkn-press-figsec"), moresec: $(".bkn-press-moresec")
};
const moreLinks = [...root.querySelectorAll(".bkn-press-more a")];
let cur = 0, hue = DATA[0].h, token = 0;

// today's date in the dateline
try {
  $(".bkn-press-today").textContent = new Intl.DateTimeFormat("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" }).format(new Date());
} catch (e) {}

// ---------- the pill: a clip-path window onto one long band ----------
function clipFor(i) {
  const t = tabs[i];
  const S = rail.scrollWidth;
  return "inset(0px " + (S - t.offsetLeft - t.offsetWidth).toFixed(1) + "px 0px " + t.offsetLeft.toFixed(1) + "px round 999px)";
}
function place(i, animate) {
  band.style.setProperty("--bkn-press-sw", rail.scrollWidth + "px");
  const next = clipFor(i);
  const from = getComputedStyle(band).clipPath;
  band.getAnimations().forEach((a) => a.cancel());
  band.style.clipPath = next;
  if (animate && !reduce.matches && from && from !== next) band.animate([{ clipPath: from }, { clipPath: next }], { duration: 560, easing: SPRING });
}
function centre(i, smooth) {
  const t = tabs[i];
  const left = t.offsetLeft + t.offsetWidth / 2 - rail.clientWidth / 2;
  rail.scrollTo({ left: Math.max(0, left), behavior: smooth && !reduce.matches ? "smooth" : "auto" });
}

// ---------- hue: take the short way round the colour wheel ----------
function tint(h) {
  let d = ((h - hue) % 360 + 540) % 360 - 180;
  hue += d;
  root.style.setProperty("--bkn-press-hue", hue.toFixed(1));
}

// ---------- the front swaps its copy with a short out / staggered in ----------
function fill(d) {
  parts.sec.textContent = d.n;
  parts.upd.textContent = d.upd;
  parts.hl.textContent = d.hl;
  parts.std.textContent = d.std;
  parts.by.textContent = d.by;
  parts.figsec.textContent = d.n;
  parts.moresec.textContent = d.n;
  moreLinks.forEach((a, k) => { a.textContent = d.more[k]; });
  root.style.setProperty("--bkn-press-sx", d.sx + "px");
}
function select(i, focus) {
  if (i === cur) { if (focus) tabs[i].focus(); return; }
  cur = i;
  tabs.forEach((t, k) => {
    t.setAttribute("aria-selected", String(k === i));
    t.tabIndex = k === i ? 0 : -1;
