  centre(i, true);
  tint(DATA[i].h);
  const my = ++token;
  const els = [...panel.querySelectorAll(".bkn-press-kick, .bkn-press-hl, .bkn-press-std, .bkn-press-by, .bkn-press-more li, .bkn-press-fig figcaption")];
  if (reduce.matches) { fill(DATA[i]); return; }
  const outs = els.map((el) => el.animate([{ opacity: 1, transform: "none" }, { opacity: 0, transform: "translateY(-6px)" }], { duration: 140, easing: "cubic-bezier(.4,0,1,1)", fill: "forwards" }));
