  const k = tabs.indexOf(document.activeElement);
  if (k < 0) return;
  let n = -1;
  if (e.key === "ArrowRight") n = (k + 1) % tabs.length;
  else if (e.key === "ArrowLeft") n = (k - 1 + tabs.length) % tabs.length;
